import React from 'react';

export interface HeaderProps {
  title?: string;
  subtitle?: string;
  supportInfo?: string;
  avatarLabel?: string;
}

export function Header({
  title = 'Welcome back',
  subtitle = 'A quick overview of what is happening today.',
  supportInfo = 'You are all set to continue where you left off.',
  avatarLabel = 'User avatar placeholder',
}: HeaderProps): React.JSX.Element {
  return (
    <header
      style={{
        display: 'flex',
        flexWrap: 'wrap',
        alignItems: 'center',
        justifyContent: 'space-between',
        gap: '1rem',
        padding: '1.25rem 1.5rem',
        borderRadius: '1rem',
        background:
          'linear-gradient(135deg, rgba(15, 23, 42, 0.96), rgba(30, 41, 59, 0.92))',
        color: '#f8fafc',
        boxShadow: '0 12px 30px rgba(15, 23, 42, 0.18)',
      }}
    >
      <div style={{ minWidth: 0, flex: '1 1 280px' }}>
        <p
          style={{
            margin: 0,
            fontSize: '0.85rem',
            fontWeight: 600,
            letterSpacing: '0.08em',
            textTransform: 'uppercase',
            color: '#94a3b8',
          }}
        >
          Dashboard
        </p>
        <h1
          style={{
            margin: '0.35rem 0 0',
            fontSize: 'clamp(1.6rem, 3vw, 2.35rem)',
            lineHeight: 1.15,
            fontWeight: 800,
            wordBreak: 'break-word',
          }}
        >
          {title}
        </h1>
        <p
          style={{
            margin: '0.6rem 0 0',
            maxWidth: '58ch',
            color: '#cbd5e1',
            fontSize: '0.98rem',
            lineHeight: 1.6,
          }}
        >
          {subtitle}
        </p>
        <p
          style={{
            margin: '0.7rem 0 0',
            maxWidth: '58ch',
            color: '#e2e8f0',
            fontSize: '0.92rem',
            lineHeight: 1.55,
          }}
        >
          {supportInfo}
        </p>
      </div>

      <div
        aria-label={avatarLabel}
        style={{
          flex: '0 1 220px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          gap: '0.9rem',
          minWidth: 0,
          padding: '0.9rem 1rem',
          borderRadius: '1rem',
          background: 'rgba(255, 255, 255, 0.08)',
          border: '1px solid rgba(255, 255, 255, 0.12)',
          backdropFilter: 'blur(10px)',
        }}
      >
        <div
          aria-hidden="true"
          style={{
            width: 56,
            height: 56,
            borderRadius: '999px',
            display: 'grid',
            placeItems: 'center',
            background: 'linear-gradient(135deg, #38bdf8, #8b5cf6)',
            color: '#fff',
            fontSize: '1.4rem',
            fontWeight: 800,
            flexShrink: 0,
            boxShadow: '0 10px 20px rgba(59, 130, 246, 0.25)',
          }}
        >
          W
        </div>
        <div style={{ minWidth: 0 }}>
          <p style={{ margin: 0, fontWeight: 700, color: '#f8fafc' }}>Welcome</p>
          <p
            style={{
              margin: '0.2rem 0 0',
              color: '#cbd5e1',
              fontSize: '0.9rem',
              lineHeight: 1.45,
            }}
          >
            {avatarLabel}
          </p>
        </div>
      </div>
    </header>
  );
}

