                        tickLine={{ stroke: '#cbd5e1' }}
                      />
                      <YAxis
                        allowDecimals={false}
                        tick={{ fill: '#475569', fontSize: 12 }}
                        axisLine={{ stroke: '#cbd5e1' }}
                        tickLine={{ stroke: '#cbd5e1' }}
                      />
                      <Tooltip
                        contentStyle={tooltipStyle}
                        labelFormatter={(label: unknown) => String(label ?? 'N/A')}
                        formatter={(value: unknown, name: unknown, item: unknown) => {
                          const numericValue = typeof value === 'number' ? value : Number(value ?? 0);
                          const safeName = typeof name === 'string' ? name : 'Value';
                          const payload =
                            item && typeof item === 'object' && 'payload' in item
                              ? (item as { payload?: SafeCategoryDatum }).payload
                              : undefined;
                          const percentage = payload?.percentage ?? 0;
                          const detail = payload?.detail ?? '';
                          const suffix = detail ? ` • ${detail}` : '';

                          return [`${numericValue} (${percentage}%)${suffix}`, safeName];
                        }}
                      />
                      <Legend wrapperStyle={legendStyle} />
                      <Bar dataKey="value" name="Share" radius={[10, 10, 0, 0]}>
                        {safeCategoryData.map((entry) => (
                          <Cell key={entry.id} fill={entry?.color ?? '#94a3b8'} />
                        ))}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                );
              })}
            />
          </div>
        ) : (
          <PlaceholderCard message="Category data is unavailable right now. Add category values to display the comparison chart." />
        )}
      </ChartCard>
    </section>
  );
}

type ResponsiveChartRendererProps = {
  render: () => Promise<React.JSX.Element>;
};

function ResponsiveChartRenderer({ render }: ResponsiveChartRendererProps): React.JSX.Element {
  const [content, setContent] = React.useState<React.JSX.Element | null>(null);

  React.useEffect(() => {
    let isMounted = true;

    void render().then((element) => {
      if (isMounted) {
        setContent(element);
      }
    });

    return () => {
      isMounted = false;
    };
  }, [render]);

  return content ?? <div style={placeholderStyle}>Loading chart…</div>;
}

