  subtitle: string;
  children: ReactNode;
};

type SafeTrendDatum = {
  label: string;
  value: number;
  secondaryValue: number;
  annotation: string;
};

type SafeCategoryDatum = {
  id: string;
  label: string;
  value: number;
  color: string;
  percentage: number;
  detail: string;
};

const sectionStyle: CSSProperties = {
  display: 'grid',
