}

function PlaceholderCard({ message }: { message: string }): React.JSX.Element {
  return <div style={placeholderStyle}>{message}</div>;
}

export default function ChartsSection({
  trendData,
  categoryData,
}: ChartsSectionProps): React.JSX.Element {
  const safeTrendData = React.useMemo<SafeTrendDatum[]>(() => {
    if (!Array.isArray(trendData) || trendData.length === 0) {
      return [];
    }

    return trendData.slice(0, 7).map((point, index) => ({
      label: point?.label ?? `Day ${index + 1}`,
      value: typeof point?.value === 'number' ? point.value : 0,
      secondaryValue: typeof point?.secondaryValue === 'number' ? point.secondaryValue : 0,
      annotation: point?.annotation ?? '',
    }));
  }, [trendData]);

  const safeCategoryData = React.useMemo<SafeCategoryDatum[]>(() => {
    if (!Array.isArray(categoryData) || categoryData.length === 0) {
      return [];
    }

    return categoryData.map((item, index) => ({
      id: item?.id ?? `category-${index}`,
      label: item?.label ?? `Category ${index + 1}`,
      value: typeof item?.value === 'number' ? item.value : 0,
      color: item?.color ?? '#94a3b8',
      percentage: typeof item?.percentage === 'number' ? item.percentage : 0,
      detail: item?.detail ?? '',
    }));
  }, [categoryData]);

  const hasTrendData = safeTrendData.length > 0;
  const hasCategoryData = safeCategoryData.length > 0;

  return (
    <section style={sectionStyle} aria-label="Charts overview section">
      <ChartCard
        title="7-Day Performance Trend"
        subtitle="Primary and secondary values across the latest seven-day period"
      >
        {hasTrendData ? (
          <div style={chartWrapperStyle}>
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={safeTrendData} margin={{ top: 12, right: 12, left: 0, bottom: 8 }}>
                <CartesianGrid stroke="#e2e8f0" strokeDasharray="3 3" />
                <XAxis
                  dataKey="label"
                  tick={{ fill: '#475569', fontSize: 12 }}
                  axisLine={{ stroke: '#cbd5e1' }}
                  tickLine={{ stroke: '#cbd5e1' }}
                />
                <YAxis
                  allowDecimals={false}
                  tick={{ fill: '#475569', fontSize: 12 }}
                  axisLine={{ stroke: '#cbd5e1' }}
                  tickLine={{ stroke: '#cbd5e1' }}
                />
                <Tooltip
                  contentStyle={tooltipContentStyle}
                  labelFormatter={(label: unknown) => String(label ?? 'N/A')}
                  formatter={(value: unknown, name: unknown, item: unknown) => {
                    const numericValue = typeof value === 'number' ? value : Number(value ?? 0);
                    const safeName = typeof name === 'string' ? name : 'Value';
                    const payload =
                      item && typeof item === 'object' && 'payload' in item
                        ? (item as { payload?: SafeTrendDatum }).payload
                        : undefined;
                    const annotation = payload?.annotation ?? '';

                    return annotation
                      ? [`${numericValue} (${annotation})`, safeName]
                      : [numericValue, safeName];
                  }}
                />
                <Legend wrapperStyle={legendWrapperStyle} />
                <Line
                  type="monotone"
                  dataKey="value"
                  name="Primary"
                  stroke="#4f46e5"
                  strokeWidth={3}
                  dot={{ r: 4, fill: '#4f46e5' }}
                  activeDot={{ r: 6 }}
                />
                <Line
                  type="monotone"
                  dataKey="secondaryValue"
                  name="Secondary"
                  stroke="#0ea5e9"
                  strokeWidth={2}
                  dot={{ r: 3, fill: '#0ea5e9' }}
                  activeDot={{ r: 5 }}
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        ) : (
          <PlaceholderCard message="Trend data is unavailable right now. Add a seven-day dataset to display the line chart." />
        )}
      </ChartCard>

      <ChartCard
        title="Category Distribution"
        subtitle="Segment totals shown as a responsive bar chart with legend and axes"
      >
        {hasCategoryData ? (
          <div style={chartWrapperStyle}>
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={safeCategoryData} margin={{ top: 12, right: 12, left: 0, bottom: 8 }}>
                <CartesianGrid stroke="#e2e8f0" strokeDasharray="3 3" />
                <XAxis
                  dataKey="label"
                  tick={{ fill: '#475569', fontSize: 12 }}
                  axisLine={{ stroke: '#cbd5e1' }}
                  tickLine={{ stroke: '#cbd5e1' }}
                />
                <YAxis
                  allowDecimals={false}
                  tick={{ fill: '#475569', fontSize: 12 }}
                  axisLine={{ stroke: '#cbd5e1' }}
                  tickLine={{ stroke: '#cbd5e1' }}
                />
                <Tooltip
                  contentStyle={tooltipContentStyle}
                  labelFormatter={(label: unknown) => String(label ?? 'N/A')}
                  formatter={(value: unknown, name: unknown, item: unknown) => {
                    const numericValue = typeof value === 'number' ? value : Number(value ?? 0);
                    const safeName = typeof name === 'string' ? name : 'Value';
                    const payload =
                      item && typeof item === 'object' && 'payload' in item
                        ? (item as { payload?: SafeCategoryDatum }).payload
                        : undefined;
                    const percentage = payload?.percentage ?? 0;
                    const detail = payload?.detail ?? '';
                    const detailSuffix = detail ? ` • ${detail}` : '';

                    return [`${numericValue} (${percentage}%)${detailSuffix}`, safeName];
                  }}
                />
                <Legend wrapperStyle={legendWrapperStyle} />
                <Bar dataKey="value" name="Share" radius={[8, 8, 0, 0]}>
                  {safeCategoryData.map((item, index) => (
                    <Cell key={item?.id ?? `cell-${index}`} fill={item?.color ?? '#94a3b8'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        ) : (
          <PlaceholderCard message="Category data is unavailable right now. Add distribution values to display the bar chart." />
        )}
      </ChartCard>
    </section>
  );
}

