                />
                <Tooltip
                  contentStyle={tooltipContentStyle}
                  labelFormatter={(label: unknown) => String(label ?? 'N/A')}
                  formatter={(value: unknown, name: unknown, item: unknown) => {
                    const numericValue = typeof value === 'number' ? value : Number(value ?? 0);
                    const safeName = typeof name === 'string' ? name : 'Value';
                    const payload =
                      item && typeof item === 'object' && 'payload' in item
                        ? (item as { payload?: SafeTrendDatum }).payload
                        : undefined;
                    const annotation = payload?.annotation ?? '';

                    return annotation
                      ? [`${numericValue} (${annotation})`, safeName]
