                  dataKey="value"
                  name="Primary"
                  stroke="#4f46e5"
                  strokeWidth={3}
                  dot={{ r: 4, fill: '#4f46e5' }}
                  activeDot={{ r: 6 }}
                />
                <Line
                  type="monotone"
                  dataKey="secondaryValue"
                  name="Secondary"
                  stroke="#0ea5e9"
                  strokeWidth={2}
                  dot={{ r: 3, fill: '#0ea5e9' }}
                  activeDot={{ r: 5 }}
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        ) : (
          <PlaceholderCard message="Trend data is unavailable right now. Add a seven-day dataset to display the line chart." />
        )}
      </ChartCard>

