import * as React from 'react';
import type { CSSProperties, ReactNode } from 'react';
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  Legend,
  Line,
  LineChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import type { CategoryChartData, TrendPoint } from '../data/dashboardData';

/** Props for the ChartsSection component. */
export interface ChartsSectionProps {
  /** Seven-day trend data used by the line chart. */
  trendData?: TrendPoint[];
  /** Category distribution data used by the secondary chart. */
  categoryData?: CategoryChartData[];
}

interface ChartCardProps {
  title: string;
  subtitle: string;
  children: ReactNode;
}

interface PlaceholderCardProps {
  message: string;
}

interface SafeTrendDatum {
  label: string;
  value: number;
  secondaryValue: number;
  annotation: string;
}

interface SafeCategoryDatum {
  id: string;
  label: string;
  value: number;
  color: string;
  percentage: number;
  detail: string;
}

const sectionStyle: CSSProperties = {
  display: 'grid',
  gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))',
  gap: '1.5rem',
  width: '100%',
};

const cardStyle: CSSProperties = {
  display: 'flex',
  flexDirection: 'column',
  gap: '1rem',
  minHeight: '360px',
  padding: '1.25rem',
  borderRadius: '20px',
  border: '1px solid #e2e8f0',
  backgroundColor: '#ffffff',
  boxShadow: '0 10px 30px rgba(15, 23, 42, 0.06)',
};

const headerStyle: CSSProperties = {
  display: 'flex',
  flexDirection: 'column',
  gap: '0.35rem',
};

const titleStyle: CSSProperties = {
  margin: 0,
  fontSize: '1.1rem',
  fontWeight: 700,
  color: '#0f172a',
};

const subtitleStyle: CSSProperties = {
  margin: 0,
  fontSize: '0.95rem',
  color: '#64748b',
  lineHeight: 1.5,
};

const chartWrapperStyle: CSSProperties = {
  width: '100%',
  minHeight: '280px',
  height: '280px',
  flex: 1,
};

const placeholderStyle: CSSProperties = {
  minHeight: '280px',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  textAlign: 'center',
  padding: '1.5rem',
  borderRadius: '16px',
  border: '1px dashed #cbd5e1',
  backgroundColor: '#f8fafc',
  color: '#64748b',
  lineHeight: 1.6,
};

const tooltipContentStyle: CSSProperties = {
  borderRadius: '12px',
  border: '1px solid #cbd5e1',
  boxShadow: '0 10px 25px rgba(15, 23, 42, 0.12)',
  backgroundColor: '#ffffff',
};

const legendWrapperStyle: CSSProperties = {
  fontSize: '0.85rem',
  paddingTop: '0.5rem',
};

function isFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}

function formatTooltipValue(value: unknown): number {
  if (isFiniteNumber(value)) {
    return value;
  }

  const parsedValue: number = Number(value ?? 0);
  return Number.isFinite(parsedValue) ? parsedValue : 0;
}

function buildSafeTrendData(data?: TrendPoint[]): SafeTrendDatum[] {
  if (!Array.isArray(data) || data.length === 0) {
    return [];
  }

  return data.slice(0, 7).map((point: TrendPoint, index: number) => ({
    label: point?.label ?? `Day ${index + 1}`,
    value: isFiniteNumber(point?.value) ? point.value : 0,
    secondaryValue: isFiniteNumber(point?.secondaryValue) ? point.secondaryValue : 0,
    annotation: point?.annotation ?? '',
  }));
}

function buildSafeCategoryData(data?: CategoryChartData[]): SafeCategoryDatum[] {
  if (!Array.isArray(data) || data.length === 0) {
    return [];
  }

  return data.map((item: CategoryChartData, index: number) => ({
    id: item?.id ?? `category-${index}`,
    label: item?.label ?? `Category ${index + 1}`,
    value: isFiniteNumber(item?.value) ? item.value : 0,
    color: item?.color ?? '#94a3b8',
    percentage: isFiniteNumber(item?.percentage) ? item.percentage : 0,
    detail: item?.detail ?? '',
  }));
}

function ChartCard({ title, subtitle, children }: ChartCardProps): React.JSX.Element {
  return (
    <article style={cardStyle}>
      <header style={headerStyle}>
        <h3 style={titleStyle}>{title}</h3>
        <p style={subtitleStyle}>{subtitle}</p>
      </header>
      {children}
    </article>
  );
}

function PlaceholderCard({ message }: PlaceholderCardProps): React.JSX.Element {
  return <div style={placeholderStyle}>{message}</div>;
}

/**
 * Renders two responsive dashboard charts with defensive fallbacks for missing datasets.
 */
export default function ChartsSection({
  trendData,
  categoryData,
}: ChartsSectionProps): React.JSX.Element {
  const safeTrendData: SafeTrendDatum[] = React.useMemo(() => buildSafeTrendData(trendData), [trendData]);
  const safeCategoryData: SafeCategoryDatum[] = React.useMemo(
    () => buildSafeCategoryData(categoryData),
    [categoryData],
  );

  const hasTrendData: boolean = safeTrendData.length > 0;
  const hasCategoryData: boolean = safeCategoryData.length > 0;

  return (
    <section style={sectionStyle} aria-label="Charts overview section">
      <ChartCard
        title="7-Day Performance Trend"
        subtitle="Primary and secondary values across the latest seven-day period"
      >
        {hasTrendData ? (
          <div style={chartWrapperStyle}>
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={safeTrendData} margin={{ top: 12, right: 12, left: 0, bottom: 8 }}>
                <CartesianGrid stroke="#e2e8f0" strokeDasharray="3 3" />
                <XAxis
                  dataKey="label"
                  tick={{ fill: '#475569', fontSize: 12 }}
                  axisLine={{ stroke: '#cbd5e1' }}
                  tickLine={{ stroke: '#cbd5e1' }}
                />
                <YAxis
                  allowDecimals={false}
                  tick={{ fill: '#475569', fontSize: 12 }}
                  axisLine={{ stroke: '#cbd5e1' }}
                  tickLine={{ stroke: '#cbd5e1' }}
                />
                <Tooltip
                  contentStyle={tooltipContentStyle}
                  labelFormatter={(label: unknown) => String(label ?? 'N/A')}
                  formatter={(value: unknown, name: unknown, item: unknown): [string | number, string] => {
                    const numericValue: number = formatTooltipValue(value);
                    const safeName: string = typeof name === 'string' ? name : 'Value';
                    const payload: SafeTrendDatum | undefined =
                      item !== null && typeof item === 'object' && 'payload' in item
                        ? (item as { payload?: SafeTrendDatum }).payload
                        : undefined;
                    const annotation: string = payload?.annotation ?? '';

                    return annotation
                      ? [`${numericValue} (${annotation})`, safeName]
                      : [numericValue, safeName];
                  }}
                />
                <Legend wrapperStyle={legendWrapperStyle} />
                <Line
                  type="monotone"
                  dataKey="value"
                  name="Primary"
                  stroke="#4f46e5"
                  strokeWidth={3}
                  dot={{ r: 4, fill: '#4f46e5' }}
                  activeDot={{ r: 6 }}
                />
                <Line
                  type="monotone"
                  dataKey="secondaryValue"
                  name="Secondary"
                  stroke="#0ea5e9"
                  strokeWidth={2}
                  dot={{ r: 3, fill: '#0ea5e9' }}
                  activeDot={{ r: 5 }}
                />
              </LineChart>
            </ResponsiveContainer>
          </div>
        ) : (
          <PlaceholderCard message="Trend data is unavailable right now. Add a seven-day dataset to display the line chart." />
        )}
      </ChartCard>

      <ChartCard
        title="Category Distribution"
        subtitle="Segment totals shown as a responsive bar chart with legend and axes"
      >
        {hasCategoryData ? (
          <div style={chartWrapperStyle}>
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={safeCategoryData} margin={{ top: 12, right: 12, left: 0, bottom: 8 }}>
                <CartesianGrid stroke="#e2e8f0" strokeDasharray="3 3" />
                <XAxis
                  dataKey="label"
                  tick={{ fill: '#475569', fontSize: 12 }}
                  axisLine={{ stroke: '#cbd5e1' }}
                  tickLine={{ stroke: '#cbd5e1' }}
                />
                <YAxis
                  allowDecimals={false}
                  tick={{ fill: '#475569', fontSize: 12 }}
                  axisLine={{ stroke: '#cbd5e1' }}
                  tickLine={{ stroke: '#cbd5e1' }}
                />
                <Tooltip
                  contentStyle={tooltipContentStyle}
                  labelFormatter={(label: unknown) => String(label ?? 'N/A')}
                  formatter={(value: unknown, name: unknown, item: unknown): [string | number, string] => {
                    const numericValue: number = formatTooltipValue(value);
                    const safeName: string = typeof name === 'string' ? name : 'Value';
                    const payload: SafeCategoryDatum | undefined =
                      item !== null && typeof item === 'object' && 'payload' in item
                        ? (item as { payload?: SafeCategoryDatum }).payload
                        : undefined;
                    const percentageSuffix: string = payload?.percentage
                      ? ` (${payload.percentage}%)`
                      : '';
                    const detailSuffix: string = payload?.detail ? ` — ${payload.detail}` : '';

                    return [`${numericValue}${percentageSuffix}${detailSuffix}`, safeName];
                  }}
                />
                <Legend wrapperStyle={legendWrapperStyle} />
                <Bar dataKey="value" name="Value" radius={[8, 8, 0, 0]}>
                  {safeCategoryData.map((entry: SafeCategoryDatum) => (
                    <Cell key={entry.id} fill={entry.color ?? '#94a3b8'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        ) : (
          <PlaceholderCard message="Category data is unavailable right now. Add distribution data to display the chart." />
        )}
      </ChartCard>
    </section>
  );
}

import * as React from 'react';

/** Props for the DashboardLayout component. */
export interface DashboardLayoutProps {
  /** Sidebar content rendered alongside the main dashboard area on desktop screens. */
  sidebar: React.ReactNode;
  /** Optional header content rendered at the top of the main content column. */
  header?: React.ReactNode;
  /** Metrics content rendered first inside the main content area. */
  metrics: React.ReactNode;
  /** Charts content rendered in the responsive secondary grid. */
  charts: React.ReactNode;
  /** Activity content rendered beside charts on larger screens and below on smaller screens. */
  activity: React.ReactNode;
  /** Optional additional class name for the outermost layout container. */
  className?: string;
}

const getContainerClasses = (className?: string): string => {
  const baseClasses = [
    'min-h-screen',
    'w-full',
    'overflow-x-hidden',
    'bg-slate-100',
    'text-slate-900',
    'lg:flex',
    'lg:items-stretch',
  ];

  if (typeof className === 'string' && className.trim()) {
    baseClasses.push(className.trim());
  }

  return baseClasses.join(' ');
};

/**
 * Provides a responsive dashboard shell with a sidebar and main content area.
 *
 * The main content is ordered as header, metrics, then a responsive charts/activity
 * grid that collapses to a single column on smaller screens while preserving
 * min-width safeguards to prevent horizontal overflow.
 */
export function DashboardLayout({
  sidebar,
  header,
  metrics,
  charts,
  activity,
  className,
}: DashboardLayoutProps): React.JSX.Element {
  return (
    <div className={getContainerClasses(className)}>
      <div className="min-w-0 shrink-0 lg:w-72 lg:max-w-[18rem] lg:basis-72">
        {sidebar}
      </div>

      <main className="min-w-0 flex-1 overflow-x-hidden">
        <div className="mx-auto flex min-w-0 w-full max-w-screen-2xl flex-col gap-6 px-4 py-4 sm:gap-6 sm:px-6 sm:py-6 lg:px-8 lg:py-8 xl:px-10">
          {header ? <div className="min-w-0">{header}</div> : null}

          <section className="min-w-0" aria-label="Dashboard metrics">
            {metrics}
          </section>

          <section
            className="grid min-w-0 grid-cols-1 gap-6 xl:grid-cols-[minmax(0,1.65fr)_minmax(0,1fr)]"
            aria-label="Dashboard insights"
          >
            <div className="min-w-0 overflow-hidden">
              {charts}
            </div>

            <div className="min-w-0 overflow-hidden">
              {activity}
            </div>
          </section>
        </div>
      </main>
    </div>
  );
}

export default DashboardLayout;

