import React from 'react';
import { render, screen } from '@testing-library/react';
import '@testing-library/jest-dom';
import { Header } from './Header';

describe('Header', () => {
  it('renders the default header content', () => {
    render(<Header />);

    expect(screen.getByText('Dashboard')).toBeInTheDocument();
    expect(
      screen.getByRole('heading', { name: 'Welcome back', level: 1 }),
    ).toBeInTheDocument();
    expect(
      screen.getByText('A quick overview of what is happening today.'),
    ).toBeInTheDocument();
    expect(
      screen.getByText('You are all set to continue where you left off.'),
    ).toBeInTheDocument();

    const avatarPanel = screen.getByLabelText('User avatar placeholder');
    expect(avatarPanel).toBeInTheDocument();
    expect(screen.getByText('Welcome')).toBeInTheDocument();
    expect(screen.getAllByText('User avatar placeholder')).toHaveLength(2);
  });

  it('renders custom props in the main content and avatar section', () => {
    render(
      <Header
        title="Team snapshot"
        subtitle="Monitor delivery status across all active workstreams."
        supportInfo="Reach out to operations if any blocker remains unresolved."
        avatarLabel="Jordan from support"
      />,
    );

    expect(
      screen.getByRole('heading', { name: 'Team snapshot', level: 1 }),
    ).toBeInTheDocument();
    expect(
      screen.getByText('Monitor delivery status across all active workstreams.'),
    ).toBeInTheDocument();
    expect(
      screen.getByText('Reach out to operations if any blocker remains unresolved.'),
    ).toBeInTheDocument();

    const avatarPanel = screen.getByLabelText('Jordan from support');
    expect(avatarPanel).toBeInTheDocument();
    expect(screen.getAllByText('Jordan from support')).toHaveLength(2);
  });

  it('falls back to defaults when props are explicitly undefined', () => {
    render(
      <Header
        title={undefined}
        subtitle={undefined}
        supportInfo={undefined}
        avatarLabel={undefined}
      />,
    );

    expect(
      screen.getByRole('heading', { name: 'Welcome back', level: 1 }),
    ).toBeInTheDocument();
    expect(screen.getByLabelText('User avatar placeholder')).toBeInTheDocument();
  });
});

import React from 'react';
import { describe, expect, it } from 'vitest';
import { render, screen } from '@testing-library/react';
import '@testing-library/jest-dom';

import MetricCards from './MetricCards';

describe('MetricCards', () => {
  it('renders metric cards for provided metrics with trend colors', () => {
    render(
      <MetricCards
        metrics={[
          {
            id: 'revenue',
            label: 'Revenue',
            value: '$12,400',
            change: '+8.2%',
            trendDirection: 'up',
          },
          {
            id: 'churn',
            label: 'Churn',
            value: '2.1%',
            change: '-0.4%',
            trendDirection: 'down',
          },
        ]}
      />,
    );

    const revenueCard = screen.getByLabelText('Revenue');
    const churnCard = screen.getByLabelText('Churn');

    expect(revenueCard).toBeInTheDocument();
    expect(churnCard).toBeInTheDocument();
    expect(screen.getByText('$12,400')).toBeInTheDocument();
    expect(screen.getByText('2.1%')).toBeInTheDocument();

    expect(screen.getByText('+8.2%')).toHaveStyle({ color: 'rgb(5, 150, 105)' });
    expect(screen.getByText('-0.4%')).toHaveStyle({ color: 'rgb(220, 38, 38)' });
  });

  it('renders an empty state when metrics are missing or empty', () => {
    const { rerender } = render(<MetricCards />);

    expect(screen.getByText('No metrics available')).toBeInTheDocument();

    rerender(<MetricCards metrics={[]} />);

    expect(screen.getByText('No metrics available')).toBeInTheDocument();
  });

  it('falls back to defaults for incomplete or whitespace-only metric fields', () => {
    render(
      <MetricCards
        metrics={[
          {
            label: '   ',
            value: '   ',
            change: '',
          },
        ]}
      />,
    );

    const card = screen.getByLabelText('Untitled metric');

    expect(card).toBeInTheDocument();
    expect(screen.getByText('Untitled metric')).toBeInTheDocument();
    expect(screen.getByText('--')).toBeInTheDocument();
    expect(screen.getByText('No change data')).toBeInTheDocument();
    expect(screen.getByText('No change data')).toHaveStyle({ color: 'rgb(100, 116, 139)' });
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

const MAIN_MODULE_PATH = './main';

describe('src/main', () => {
  const originalRoot = document.getElementById('root');

  beforeEach(() => {
    vi.resetModules();
    vi.unmock('./App');
    vi.unmock('react-dom/client');
    document.body.innerHTML = '';
  });

  afterEach(() => {
    document.body.innerHTML = '';
    if (originalRoot) {
      document.body.appendChild(originalRoot);
    }
    vi.clearAllMocks();
  });

  it('creates a React root on #root and renders App inside StrictMode', async () => {
    document.body.innerHTML = '<div id="root"></div>';

    const render = vi.fn();
    const createRoot = vi.fn(() => ({ render }));

    vi.doMock('./App', () => ({
      default: () => <div data-testid="app">Mock App</div>,
    }));

    vi.doMock('react-dom/client', () => ({
      createRoot,
    }));

    await import(MAIN_MODULE_PATH);

    const rootElement = document.getElementById('root');
    expect(createRoot).toHaveBeenCalledTimes(1);
    expect(createRoot).toHaveBeenCalledWith(rootElement);
    expect(render).toHaveBeenCalledTimes(1);

    const renderedTree = render.mock.calls[0][0];
    expect(renderedTree.type).toBeDefined();
    expect(renderedTree.type).toBeSymbol?.();
  });

  it('renders StrictMode with App as its child', async () => {
    document.body.innerHTML = '<div id="root"></div>';

    const render = vi.fn();

    vi.doMock('./App', () => ({
      default: () => <div>Mock App</div>,
    }));

    vi.doMock('react-dom/client', () => ({
      createRoot: vi.fn(() => ({ render })),
    }));

    const React = await import('react');
    const mainModule = import(MAIN_MODULE_PATH);
    await mainModule;

    const element = render.mock.calls[0][0];
    expect(element.type).toBe(React.StrictMode);
    expect(element.props.children.type).toBeTypeOf('function');
  });

  it('throws a clear error when the root element is missing', async () => {
    vi.doMock('./App', () => ({
      default: () => <div>Mock App</div>,
    }));

    const createRoot = vi.fn();
    vi.doMock('react-dom/client', () => ({
      createRoot,
    }));

    await expect(import(MAIN_MODULE_PATH)).rejects.toThrow(
      'Root element with id "root" was not found.',
    );
    expect(createRoot).not.toHaveBeenCalled();
  });
});

