    const metricsSection = screen.getByLabelText('Dashboard metrics');
    expect(within(metricsSection).getByText('Metrics content')).toBeInTheDocument();

    const insightsSection = screen.getByLabelText('Dashboard insights');
    expect(within(insightsSection).getByText('Charts content')).toBeInTheDocument();
    expect(within(insightsSection).getByText('Activity content')).toBeInTheDocument();

    expect(container.firstChild).toHaveClass(
