      <DashboardLayout
        sidebar={<div>Sidebar only</div>}
        metrics={<div>Metrics only</div>}
        charts={<div>Charts only</div>}
        activity={<div>Activity only</div>}
      />,
    );

    expect(screen.queryByText('Header only')).not.toBeInTheDocument();
    expect(screen.getByText('Sidebar only')).toBeInTheDocument();
    expect(screen.getByLabelText('Dashboard metrics')).toBeInTheDocument();
    expect(screen.getByLabelText('Dashboard insights')).toBeInTheDocument();
  });

  it('does not include a whitespace-only className in the container classes', () => {
    const { container } = render(
      <DashboardLayout
        sidebar={<div>Sidebar</div>}
        header={<div>Header</div>}
        metrics={<div>Metrics</div>}
        charts={<div>Charts</div>}
        activity={<div>Activity</div>}
        className="   "
      />,
    );

    expect(container.firstChild).toHaveClass(
      'min-h-screen',
      'w-full',
      'overflow-x-hidden',
      'bg-slate-100',
      'text-slate-900',
      'lg:flex',
      'lg:items-stretch',
    );
    expect(container.firstChild).not.toHaveAttribute('class', expect.stringContaining('   '));
  });
});

