        supportInfo={undefined}
        avatarLabel={undefined}
      />,
    );

    expect(
      screen.getByRole('heading', { name: 'Welcome back', level: 1 }),
    ).toBeInTheDocument();
    expect(screen.getByLabelText('User avatar placeholder')).toBeInTheDocument();
  });
});

