import * as React from 'react';
import { describe, expect, it, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import type { CategoryChartData, TrendPoint } from '../data/dashboardData';
import ChartsSection from './ChartsSection';

const rechartsSpies = vi.hoisted(() => ({
  lineChart: vi.fn(),
  barChart: vi.fn(),
  line: vi.fn(),
  bar: vi.fn(),
  cell: vi.fn(),
  tooltip: vi.fn(),
  responsiveContainer: vi.fn(),
}));

vi.mock('recharts', async () => {
  const ReactModule = await vi.importActual<typeof import('react')>('react');
  const React = ReactModule;

  const makeComponent = (name: string, spy?: ReturnType<typeof vi.fn>) => {
    const Component = ({ children, ...props }: any) => {
      spy?.(props);
      return React.createElement(
        'div',
        {
          'data-testid': name,
          ...(props['aria-label'] ? { 'aria-label': props['aria-label'] } : {}),
        },
        children,
      );
    };

    return Component;
  };

  return {
    ResponsiveContainer: makeComponent('ResponsiveContainer', rechartsSpies.responsiveContainer),
    LineChart: makeComponent('LineChart', rechartsSpies.lineChart),
    BarChart: makeComponent('BarChart', rechartsSpies.barChart),
    CartesianGrid: makeComponent('CartesianGrid'),
    XAxis: makeComponent('XAxis'),
    YAxis: makeComponent('YAxis'),
    Legend: makeComponent('Legend'),
    Tooltip: makeComponent('Tooltip', rechartsSpies.tooltip),
    Line: makeComponent('Line', rechartsSpies.line),
    Bar: makeComponent('Bar', rechartsSpies.bar),
    Cell: makeComponent('Cell', rechartsSpies.cell),
  };
});

describe('ChartsSection', () => {
  it('renders both chart cards and passes sanitized datasets to the chart components', () => {
    const trendData: TrendPoint[] = [
      { label: 'Mon', value: 10, secondaryValue: 3, annotation: 'steady' },
      { label: 'Tue', value: 12, secondaryValue: 4 },
      { label: 'Wed', value: 14, secondaryValue: 5 },
      { label: 'Thu', value: 16, secondaryValue: 6 },
      { label: 'Fri', value: 18, secondaryValue: 7 },
      { label: 'Sat', value: 20, secondaryValue: 8 },
      { label: 'Sun', value: 22, secondaryValue: 9 },
      { label: 'Extra', value: 99, secondaryValue: 99, annotation: 'ignored' },
    ];

    const categoryData: CategoryChartData[] = [
      { id: 'a', label: 'Alpha', value: 40, color: '#111111', percentage: 40, detail: 'top' },
      { id: 'b', label: 'Beta', value: 60, color: '#222222', percentage: 60, detail: 'next' },
    ];

    render(<ChartsSection trendData={trendData} categoryData={categoryData} />);

    expect(screen.getByLabelText('Charts overview section')).toBeInTheDocument();
    expect(screen.getByText('7-Day Performance Trend')).toBeInTheDocument();
    expect(screen.getByText('Category Distribution')).toBeInTheDocument();

    expect(screen.getByTestId('LineChart')).toBeInTheDocument();
    expect(screen.getByTestId('BarChart')).toBeInTheDocument();

    expect(rechartsSpies.lineChart).toHaveBeenCalled();
    expect(rechartsSpies.barChart).toHaveBeenCalled();

    const lineChartProps = rechartsSpies.lineChart.mock.calls[0][0];
    const barChartProps = rechartsSpies.barChart.mock.calls[0][0];

    expect(lineChartProps.data).toHaveLength(7);
    expect(lineChartProps.data.map((point: TrendPoint) => point.label)).toEqual([
      'Mon',
      'Tue',
      'Wed',
      'Thu',
      'Fri',
      'Sat',
      'Sun',
    ]);
    expect(barChartProps.data).toEqual([
      { id: 'a', label: 'Alpha', value: 40, color: '#111111', percentage: 40, detail: 'top' },
      { id: 'b', label: 'Beta', value: 60, color: '#222222', percentage: 60, detail: 'next' },
    ]);
  });

  it('shows placeholder cards when trend and category data are missing', () => {
    render(<ChartsSection />);

    expect(
      screen.getByText('Trend data is unavailable right now. Add a seven-day dataset to display the line chart.'),
    ).toBeInTheDocument();
    expect(
      screen.getByText('Category data is unavailable right now. Add category totals to display the bar chart.'),
    ).toBeInTheDocument();

    expect(screen.queryByTestId('LineChart')).not.toBeInTheDocument();
    expect(screen.queryByTestId('BarChart')).not.toBeInTheDocument();
  });

  it('normalizes invalid values and fallback labels in chart data', () => {
    const invalidTrendData = [
      {
        label: undefined,
        value: Number.NaN,
        secondaryValue: Number.POSITIVE_INFINITY,
        annotation: undefined,
      },
    ] as unknown as TrendPoint[];

    const invalidCategoryData = [
      {
        id: undefined,
        label: undefined,
        value: Number.NaN,
        color: undefined,
        percentage: Number.POSITIVE_INFINITY,
        detail: undefined,
      },
    ] as unknown as CategoryChartData[];

    render(<ChartsSection trendData={invalidTrendData} categoryData={invalidCategoryData} />);

    const lineChartProps = rechartsSpies.lineChart.mock.calls.at(-1)?.[0];
    const barChartProps = rechartsSpies.barChart.mock.calls.at(-1)?.[0];

    expect(lineChartProps.data).toEqual([
      { label: 'Day 1', value: 0, secondaryValue: 0, annotation: '' },
    ]);
    expect(barChartProps.data).toEqual([
      {
        id: 'category-0',
        label: 'Category 1',
        value: 0,
        color: '#94a3b8',
        percentage: 0,
        detail: '',
      },
    ]);
  });
});

