import React from 'react';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, expect, it } from 'vitest';
import App from './App';
import { navigationItems } from './data/dashboardData';

describe('App', () => {
  it('renders the dashboard using the initially active navigation item', () => {
    render(<App />);

    const initialItem = navigationItems.find((item) => item.isActive) ?? navigationItems[0];

    expect(
      screen.getByRole('heading', { level: 1, name: initialItem.label }),
    ).toBeInTheDocument();
    expect(screen.getByText(initialItem.description ?? 'Operational insights for your team.')).toBeInTheDocument();
    expect(
      screen.getByText(
        'All dashboard data is rendered locally with no routing, background sync, or network requests.',
      ),
    ).toBeInTheDocument();

    expect(screen.getByRole('navigation', { name: /primary navigation/i })).toBeInTheDocument();
    expect(screen.getByRole('region', { name: /dashboard metrics/i })).toBeInTheDocument();
    expect(screen.getByRole('region', { name: /dashboard insights/i })).toBeInTheDocument();
  });

  it('updates the header when a different section is selected', async () => {
    const user = userEvent.setup();
    render(<App />);

    const analyticsItem = navigationItems.find((item) => item.id === 'analytics');
    expect(analyticsItem).toBeDefined();

    await user.click(screen.getByRole('button', { name: /analytics/i }));

    expect(
      screen.getByRole('heading', { level: 1, name: analyticsItem!.label }),
    ).toBeInTheDocument();
    expect(screen.getByText(analyticsItem!.description!)).toBeInTheDocument();
  });

  it('shows default subtitle copy for a section without a description', async () => {
    const user = userEvent.setup();
    render(<App />);

    const fallbackItem = navigationItems.find((item) => item.id === 'settings' && !item.description)
      ?? navigationItems.find((item) => !item.description);

    expect(fallbackItem).toBeDefined();

    await user.click(screen.getByRole('button', { name: new RegExp(fallbackItem!.label, 'i') }));

    expect(
      screen.getByRole('heading', { level: 1, name: fallbackItem!.label }),
    ).toBeInTheDocument();
    expect(screen.getByText('Operational insights for your team.')).toBeInTheDocument();
  });
});

