import React from 'react';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, expect, it } from 'vitest';
import App from './App';
import { navigationItems } from './data/dashboardData';

describe('App', () => {
  it('renders the dashboard using the initially active navigation item', () => {
    render(<App />);

    const initialItem = navigationItems.find((item) => item.isActive) ?? navigationItems[0];

    expect(
      screen.getByRole('heading', { level: 1, name: initialItem.label }),
    ).toBeInTheDocument();
    expect(screen.getByText(initialItem.description!)).toBeInTheDocument();
    expect(
      screen.getByText(
        'All dashboard data is rendered locally with no routing, background sync, or network requests.',
      ),
    ).toBeInTheDocument();

    const selectedNavButton = screen.getByRole('button', { name: new RegExp(initialItem.label, 'i') });
    expect(selectedNavButton).toHaveAttribute('aria-current', 'page');
  });

  it('updates the header and active navigation state when a different section is selected', async () => {
    const user = userEvent.setup();
    render(<App />);

    const analyticsButton = screen.getByRole('button', { name: /analytics/i });
    await user.click(analyticsButton);

    expect(screen.getByRole('heading', { level: 1, name: 'Analytics' })).toBeInTheDocument();
    expect(screen.getByText('Performance trends and funnel insights')).toBeInTheDocument();
    expect(analyticsButton).toHaveAttribute('aria-current', 'page');

    const overviewButton = screen.getByRole('button', { name: /overview/i });
    expect(overviewButton).not.toHaveAttribute('aria-current', 'page');
  });

  it('falls back to default header copy when a navigation item without description is selected', async () => {
    const user = userEvent.setup();
    render(<App />);

    await user.click(screen.getByRole('button', { name: /settings/i }));

    expect(screen.getByRole('heading', { level: 1, name: 'Settings' })).toBeInTheDocument();
    expect(screen.getByText('Operational insights for your team.')).toBeInTheDocument();
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

const MAIN_MODULE_PATH = './main';

describe('src/main', () => {
  beforeEach(() => {
    vi.resetModules();
    vi.unmock('./App');
    vi.unmock('react-dom/client');
    document.body.innerHTML = '';
  });

  afterEach(() => {
    document.body.innerHTML = '';
    vi.clearAllMocks();
  });

  it('creates a React root on #root and renders App inside StrictMode', async () => {
    document.body.innerHTML = '<div id="root"></div>';

    const render = vi.fn();
    const createRoot = vi.fn(() => ({ render }));

    vi.doMock('./App', () => ({
      default: () => <div data-testid="app">Mock App</div>,
    }));

    vi.doMock('react-dom/client', () => ({
      createRoot,
    }));

    const React = await import('react');

    await import(MAIN_MODULE_PATH);

    const rootElement = document.getElementById('root');
    expect(createRoot).toHaveBeenCalledTimes(1);
    expect(createRoot).toHaveBeenCalledWith(rootElement);
    expect(render).toHaveBeenCalledTimes(1);

    const renderedTree = render.mock.calls[0][0];
    expect(renderedTree.type).toBe(React.StrictMode);
    expect(renderedTree.props.children.type).toBeTypeOf('function');
  });

  it('renders the App component as the child of StrictMode', async () => {
    document.body.innerHTML = '<div id="root"></div>';

    const render = vi.fn();
    const mockedApp = vi.fn(() => <div>Mock App</div>);

    vi.doMock('./App', () => ({
      default: mockedApp,
    }));

    vi.doMock('react-dom/client', () => ({
      createRoot: vi.fn(() => ({ render })),
    }));

    await import(MAIN_MODULE_PATH);

    const element = render.mock.calls[0][0];
    expect(element.props.children.type).toBe(mockedApp);
  });

  it('throws a clear error when the root element is missing', async () => {
    vi.doMock('./App', () => ({
      default: () => <div>Mock App</div>,
    }));

    const createRoot = vi.fn();
    vi.doMock('react-dom/client', () => ({
      createRoot,
    }));

    await expect(import(MAIN_MODULE_PATH)).rejects.toThrow(
      'Root element with id "root" was not found.',
    );
    expect(createRoot).not.toHaveBeenCalled();
  });
});

