import * as React from 'react';
import { render, screen } from '@testing-library/react';
import { describe, expect, it, vi } from 'vitest';
import ChartsSection from './ChartsSection';

vi.mock('recharts', () => {
  const React = require('react');

  const makeComponent = (name: string) => {
    return ({ children, ...props }: any) =>
      React.createElement(
        'div',
        {
          'data-testid': name,
          ...props,
        },
        children,
      );
  };

  return {
    ResponsiveContainer: makeComponent('responsive-container'),
    LineChart: makeComponent('line-chart'),
    BarChart: makeComponent('bar-chart'),
    CartesianGrid: makeComponent('cartesian-grid'),
    XAxis: makeComponent('x-axis'),
    YAxis: makeComponent('y-axis'),
    Legend: makeComponent('legend'),
    Line: makeComponent('line'),
    Bar: makeComponent('bar'),
    Cell: makeComponent('cell'),
    Tooltip: ({ formatter, labelFormatter }: any) => {
      const formatted = formatter?.('12', 'Primary', { payload: { annotation: 'Peak' } });
      const formattedWithoutAnnotation = formatter?.('bad-value', 42, { payload: {} });
      const label = labelFormatter?.(null);

      return React.createElement(
        'div',
        { 'data-testid': 'tooltip' },
        React.createElement('span', { 'data-testid': 'tooltip-label' }, String(label)),
        React.createElement(
          'span',
          { 'data-testid': 'tooltip-formatted' },
          JSON.stringify(formatted),
        ),
        React.createElement(
          'span',
          { 'data-testid': 'tooltip-formatted-fallback' },
          JSON.stringify(formattedWithoutAnnotation),
        ),
      );
    },
  };
});

describe('ChartsSection', () => {
  it('renders both chart cards with chart content when valid datasets are provided', () => {
    render(
      <ChartsSection
        trendData={[
          { label: 'Mon', value: 10, secondaryValue: 4, annotation: 'Peak' },
          { label: 'Tue', value: 8, secondaryValue: 3, annotation: 'Steady' },
        ]}
        categoryData={[
          { id: 'a', label: 'Alpha', value: 30, color: '#ff0000', percentage: 60, detail: 'Top' },
          { id: 'b', label: 'Beta', value: 20, color: '#00ff00', percentage: 40, detail: 'Second' },
        ]}
      />,
    );

    expect(screen.getByRole('region', { name: 'Charts overview section' })).toBeInTheDocument();
    expect(screen.getByText('7-Day Performance Trend')).toBeInTheDocument();
    expect(screen.getByText('Category Distribution')).toBeInTheDocument();
    expect(screen.getByTestId('line-chart')).toBeInTheDocument();
    expect(screen.getByTestId('bar-chart')).toBeInTheDocument();
    expect(screen.getAllByTestId('responsive-container')).toHaveLength(2);
  });

  it('renders placeholder cards when data is missing', () => {
    render(<ChartsSection />);

    expect(
      screen.getByText(/Trend data is unavailable right now\. Add a seven-day dataset to display the line chart\./i),
    ).toBeInTheDocument();
    expect(
      screen.getByText(/Category data is unavailable right now\. Add distribution values to display the bar chart\./i),
    ).toBeInTheDocument();
    expect(screen.queryByTestId('line-chart')).not.toBeInTheDocument();
    expect(screen.queryByTestId('bar-chart')).not.toBeInTheDocument();
  });

  it('sanitizes invalid trend values for tooltip formatting and still renders charts for partial data', () => {
    render(
      <ChartsSection
        trendData={[
          { label: 'Mon', value: Number.NaN as unknown as number, secondaryValue: Infinity as unknown as number, annotation: undefined as never },
        ]}
        categoryData={[{ id: 'only', label: undefined as never, value: Number.NaN as unknown as number }] as any}
      />,
    );

    expect(screen.getByTestId('line-chart')).toBeInTheDocument();
    expect(screen.getByTestId('bar-chart')).toBeInTheDocument();
    expect(screen.getByTestId('tooltip-label')).toHaveTextContent('N/A');
    expect(screen.getByTestId('tooltip-formatted')).toHaveTextContent('["12 (Peak)","Primary"]');
    expect(screen.getByTestId('tooltip-formatted-fallback')).toHaveTextContent('[0,"Value"]');
  });
});

