import React from 'react';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, expect, it } from 'vitest';
import App from './App';
import { navigationItems } from './data/dashboardData';

describe('App', () => {
  it('renders the dashboard with the initial active navigation content', () => {
    const initialItem =
      navigationItems.find((item) => item.isActive === true && item.id.trim().length > 0) ??
      navigationItems.find((item) => item.id.trim().length > 0);

    expect(initialItem).toBeDefined();

    render(<App />);

    expect(
      screen.getByRole('heading', { name: initialItem!.label, level: 1 }),
    ).toBeInTheDocument();
    expect(screen.getByText(initialItem!.description!)).toBeInTheDocument();
    expect(
      screen.getByText(
        'All dashboard data is rendered locally with no routing, background sync, or network requests.',
      ),
    ).toBeInTheDocument();
    expect(screen.getByRole('button', { name: initialItem!.label })).toHaveAttribute(
      'aria-current',
      'page',
    );
  });

  it('updates the selected section and header copy when a different navigation item is chosen', async () => {
    const user = userEvent.setup();
    render(<App />);

    const nextItem = navigationItems.find((item) => item.id === 'analytics')!;
    await user.click(screen.getByRole('button', { name: nextItem.label }));

    expect(screen.getByRole('heading', { name: nextItem.label, level: 1 })).toBeInTheDocument();
    expect(screen.getByText(nextItem.description!)).toBeInTheDocument();
    expect(screen.getByRole('button', { name: nextItem.label })).toHaveAttribute(
      'aria-current',
      'page',
    );
  });

  it('falls back to the default subtitle when selecting an item without a description', async () => {
    const user = userEvent.setup();
    render(<App />);

    const fallbackItem = navigationItems.find((item) => item.id === 'operations')!;
    await user.click(screen.getByRole('button', { name: fallbackItem.label }));

    expect(screen.getByRole('heading', { name: fallbackItem.label, level: 1 })).toBeInTheDocument();
    expect(screen.getByText('Operational insights for your team.')).toBeInTheDocument();
    expect(screen.getByRole('button', { name: fallbackItem.label })).toHaveAttribute(
      'aria-current',
      'page',
    );
  });
});

