import * as React from 'react';
import { render, screen } from '@testing-library/react';
import { describe, expect, it, vi } from 'vitest';
import ChartsSection from './ChartsSection';

const rechartsState = vi.hoisted(() => ({
  lineChartData: undefined as unknown,
  barChartData: undefined as unknown,
  lineNames: [] as string[],
  barDataKeys: [] as string[],
  cellFills: [] as string[],
}));

vi.mock('recharts', () => {
  const React = require('react');

  return {
    ResponsiveContainer: ({ children }: { children: React.ReactNode }) => (
      <div data-testid="responsive-container">{children}</div>
    ),
    LineChart: ({ data, children }: { data: unknown; children: React.ReactNode }) => {
      rechartsState.lineChartData = data;
      return <div data-testid="line-chart">{children}</div>;
    },
    BarChart: ({ data, children }: { data: unknown; children: React.ReactNode }) => {
      rechartsState.barChartData = data;
      return <div data-testid="bar-chart">{children}</div>;
    },
    CartesianGrid: () => <div data-testid="cartesian-grid" />,
    XAxis: () => <div data-testid="x-axis" />,
    YAxis: () => <div data-testid="y-axis" />,
    Tooltip: () => <div data-testid="tooltip" />,
    Legend: () => <div data-testid="legend" />,
    Line: ({ name }: { name?: string }) => {
      if (name) rechartsState.lineNames.push(name);
      return <div data-testid={`line-${String(name ?? 'unnamed').toLowerCase()}`} />;
    },
    Bar: ({ dataKey, children }: { dataKey?: string; children?: React.ReactNode }) => {
      if (dataKey) rechartsState.barDataKeys.push(dataKey);
      return <div data-testid={`bar-${String(dataKey ?? 'unnamed').toLowerCase()}`}>{children}</div>;
    },
    Cell: ({ fill }: { fill?: string }) => {
      if (fill) rechartsState.cellFills.push(fill);
      return <div data-testid="cell" />;
    },
  };
});

describe('ChartsSection', () => {
  const resetRechartsState = (): void => {
    rechartsState.lineChartData = undefined;
    rechartsState.barChartData = undefined;
    rechartsState.lineNames = [];
    rechartsState.barDataKeys = [];
    rechartsState.cellFills = [];
  };

  it('renders both chart cards and passes sanitized datasets to the charts on the happy path', () => {
    resetRechartsState();

    const trendData = [
      { label: 'Mon', value: 10, secondaryValue: 4, annotation: 'steady' },
      { label: 'Tue', value: 12, secondaryValue: 6, annotation: 'up' },
    ];
    const categoryData = [
      { id: 'cat-a', label: 'Category A', value: 30, color: '#111111', percentage: 60, detail: 'Top performer' },
      { id: 'cat-b', label: 'Category B', value: 20, color: '#222222', percentage: 40, detail: 'Secondary' },
    ];

    render(<ChartsSection trendData={trendData} categoryData={categoryData} />);

    expect(screen.getByRole('region', { name: 'Charts overview section' })).toBeInTheDocument();
    expect(screen.getByText('7-Day Performance Trend')).toBeInTheDocument();
    expect(screen.getByText('Category Distribution')).toBeInTheDocument();
    expect(screen.getByTestId('line-chart')).toBeInTheDocument();
    expect(screen.getByTestId('bar-chart')).toBeInTheDocument();

    expect(rechartsState.lineChartData).toEqual([
      { label: 'Mon', value: 10, secondaryValue: 4, annotation: 'steady' },
      { label: 'Tue', value: 12, secondaryValue: 6, annotation: 'up' },
    ]);
    expect(rechartsState.barChartData).toEqual([
      { id: 'cat-a', label: 'Category A', value: 30, color: '#111111', percentage: 60, detail: 'Top performer' },
      { id: 'cat-b', label: 'Category B', value: 20, color: '#222222', percentage: 40, detail: 'Secondary' },
    ]);
    expect(rechartsState.lineNames).toEqual(expect.arrayContaining(['Primary', 'Secondary']));
    expect(rechartsState.barDataKeys).toContain('value');
    expect(rechartsState.cellFills).toEqual(expect.arrayContaining(['#111111', '#222222']));
  });

  it('shows placeholder messaging when both datasets are missing', () => {
    resetRechartsState();

    render(<ChartsSection />);

    expect(
      screen.getByText(/Trend data is unavailable right now\. Add a seven-day dataset to display the line chart\./i),
    ).toBeInTheDocument();
    expect(screen.getByText(/category data is unavailable/i)).toBeInTheDocument();
    expect(screen.queryByTestId('line-chart')).not.toBeInTheDocument();
    expect(screen.queryByTestId('bar-chart')).not.toBeInTheDocument();
  });

  it('defensively normalizes invalid values and limits trend data to seven points', () => {
    resetRechartsState();

    const trendData = [
      { label: 'D1', value: 1, secondaryValue: 2, annotation: 'a' },
      { label: 'D2', value: Number.NaN, secondaryValue: Infinity, annotation: 'b' },
      { label: undefined, value: undefined, secondaryValue: undefined, annotation: undefined },
      { label: 'D4', value: 4, secondaryValue: 5, annotation: 'd' },
      { label: 'D5', value: 5, secondaryValue: 6, annotation: 'e' },
      { label: 'D6', value: 6, secondaryValue: 7, annotation: 'f' },
      { label: 'D7', value: 7, secondaryValue: 8, annotation: 'g' },
      { label: 'D8', value: 8, secondaryValue: 9, annotation: 'h' },
    ];

    const categoryData = [
      { id: undefined, label: undefined, value: Number.NaN, color: undefined, percentage: Infinity, detail: undefined },
    ];

    render(<ChartsSection trendData={trendData as never} categoryData={categoryData as never} />);

    expect(rechartsState.lineChartData).toEqual([
      { label: 'D1', value: 1, secondaryValue: 2, annotation: 'a' },
      { label: 'D2', value: 0, secondaryValue: 0, annotation: 'b' },
      { label: 'Day 3', value: 0, secondaryValue: 0, annotation: '' },
      { label: 'D4', value: 4, secondaryValue: 5, annotation: 'd' },
      { label: 'D5', value: 5, secondaryValue: 6, annotation: 'e' },
      { label: 'D6', value: 6, secondaryValue: 7, annotation: 'f' },
      { label: 'D7', value: 7, secondaryValue: 8, annotation: 'g' },
    ]);
    expect(rechartsState.barChartData).toEqual([
      {
        id: 'category-0',
        label: 'Category 1',
        value: 0,
        color: '#94a3b8',
        percentage: 0,
        detail: '',
      },
    ]);
  });
});

