import * as React from 'react';
import { fireEvent, render, screen } from '@testing-library/react';
import { describe, expect, it } from 'vitest';

import App from './App';
import { navigationItems } from './data/dashboardData';

describe('App', () => {
  it('renders the dashboard with the initially active navigation item content', () => {
    const initialItem = navigationItems.find(
      (item) => item.isActive === true && item.id.trim().length > 0,
    ) ?? navigationItems.find((item) => item.id.trim().length > 0);

    expect(initialItem).toBeDefined();

    render(<App />);

    expect(
      screen.getByRole('heading', { name: initialItem!.label, level: 1 }),
    ).toBeInTheDocument();

    if (initialItem?.description) {
      expect(screen.getByText(initialItem.description)).toBeInTheDocument();
    }

    expect(
      screen.getByText(
        'All dashboard data is rendered locally with no routing, background sync, or network requests.',
      ),
    ).toBeInTheDocument();

    const activeNavButton = screen.getByRole('button', { name: initialItem!.label });
    expect(activeNavButton).toHaveAttribute('aria-pressed', 'true');
    expect(activeNavButton).toHaveAttribute('aria-current', 'page');
  });

  it('updates the selected section header and active navigation state when a different item is chosen', () => {
    const targetItem = navigationItems.find((item) => item.id === 'analytics') ?? navigationItems[1];

    render(<App />);

    fireEvent.click(screen.getByRole('button', { name: targetItem.label }));

    expect(
      screen.getByRole('heading', { name: targetItem.label, level: 1 }),
    ).toBeInTheDocument();

    if (targetItem.description) {
      expect(screen.getByText(targetItem.description)).toBeInTheDocument();
    }

    const selectedButton = screen.getByRole('button', { name: targetItem.label });
    expect(selectedButton).toHaveAttribute('aria-pressed', 'true');
    expect(selectedButton).toHaveAttribute('aria-current', 'page');

    const otherActiveButtons = screen
      .getAllByRole('button')
      .filter((button) => button.getAttribute('aria-pressed') === 'true');
    expect(otherActiveButtons).toHaveLength(1);
  });

  it('ignores blank navigation selections and keeps the current view unchanged', () => {
    render(<App />);

    const initialHeading = screen.getByRole('heading', { level: 1 });
    const initialHeadingText = initialHeading.textContent;

    const reportsButton = screen.getByRole('button', { name: /analytics/i });
    fireEvent.click(reportsButton);
    expect(screen.getByRole('heading', { name: /analytics/i, level: 1 })).toBeInTheDocument();

    const whitespaceTrigger = document.createElement('button');
    whitespaceTrigger.textContent = 'Whitespace trigger';
    whitespaceTrigger.addEventListener('click', () => {
      const event = new CustomEvent('app-test-select-blank');
      window.dispatchEvent(event);
    });
    document.body.appendChild(whitespaceTrigger);

    const sidebarButtons = screen.getAllByRole('button');
    const selectedBefore = sidebarButtons.find((button) => button.getAttribute('aria-pressed') === 'true');
    expect(selectedBefore).toHaveTextContent(/analytics/i);

    document.body.removeChild(whitespaceTrigger);

    expect(screen.getByRole('heading', { name: /analytics/i, level: 1 })).toBeInTheDocument();
    expect(screen.queryByRole('heading', { name: initialHeadingText ?? '', level: 1 })).not.toBeInTheDocument();
  });
});

import * as React from 'react';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, expect, it, vi } from 'vitest';
import { Sidebar } from './Sidebar';
import type { NavigationItem } from '../data/dashboardData';

describe('Sidebar', () => {
  const items: NavigationItem[] = [
    {
      id: 'overview',
      label: 'Overview',
      description: 'Summary metrics',
      icon: 'ov',
      badgeCount: 3,
    },
    {
      id: 'pipeline',
      label: 'Pipeline',
      description: 'Revenue forecast',
      badgeCount: 0,
    },
    {
      id: 'alerts',
      label: 'Alerts',
      icon: ' ',
    },
  ];

  it('renders navigation items and highlights the selected item', () => {
    render(
      <Sidebar items={items} selectedItemId="overview" onSelect={vi.fn()} />,
    );

    expect(
      screen.getByRole('navigation', { name: /primary navigation/i }),
    ).toBeInTheDocument();

    const overviewButton = screen.getByRole('button', { name: /overview/i });
    const pipelineButton = screen.getByRole('button', { name: /pipeline/i });

    expect(overviewButton).toHaveAttribute('aria-current', 'page');
    expect(overviewButton).toHaveAttribute('aria-pressed', 'true');
    expect(pipelineButton).toHaveAttribute('aria-pressed', 'false');

    expect(screen.getByText('Summary metrics')).toBeInTheDocument();
    expect(screen.getByLabelText('3 notifications')).toBeInTheDocument();
    expect(screen.getByLabelText('0 notifications')).toBeInTheDocument();
  });

  it('calls onSelect with the clicked item id', async () => {
    const user = userEvent.setup();
    const onSelect = vi.fn();

    render(
      <Sidebar items={items} selectedItemId="overview" onSelect={onSelect} />,
    );

    await user.click(screen.getByRole('button', { name: /pipeline/i }));

    expect(onSelect).toHaveBeenCalledTimes(1);
    expect(onSelect).toHaveBeenCalledWith('pipeline');
  });

  it('falls back to the label monogram when icon is missing or blank and omits optional metadata', () => {
    render(<Sidebar items={items} selectedItemId="alerts" onSelect={vi.fn()} />);

    expect(screen.getByText('PI')).toBeInTheDocument();
    expect(screen.getByText('AL')).toBeInTheDocument();
    expect(screen.queryByText('Revenue forecast')).not.toBeInTheDocument();
    expect(screen.queryByLabelText(/notifications/i, { selector: '[aria-label="undefined notifications"]' })).not.toBeInTheDocument();
  });
});

