import App from './App';
import { navigationItems } from './data/dashboardData';

describe('App', () => {
  it('renders the dashboard with the initially active navigation section content', () => {
    const activeItem = navigationItems.find((item) => item.isActive) ?? navigationItems[0];

    render(<App />);

    expect(
      screen.getByRole('heading', { level: 1, name: activeItem.label }),
    ).toBeInTheDocument();
    expect(screen.getByText(activeItem.description ?? 'Operational insights for your team.')).toBeInTheDocument();
    expect(
      screen.getByText(
        'All dashboard data is rendered locally with no routing, background sync, or network requests.',
      ),
    ).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /analytics/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /customers/i })).toBeInTheDocument();
  });

  it('updates the selected section and header copy when a different navigation item is chosen', () => {
    render(<App />);

    fireEvent.click(screen.getByRole('button', { name: /analytics/i }));

    expect(screen.getByRole('heading', { level: 1, name: 'Analytics' })).toBeInTheDocument();
    expect(screen.getByText('Performance trends and funnel insights')).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /analytics/i })).toHaveAttribute('aria-current', 'page');
    expect(screen.getByRole('button', { name: /overview/i })).not.toHaveAttribute('aria-current', 'page');
  });

  it('falls back to generic header content when selecting a non-seeded navigation id', () => {
    render(<App />);

    fireEvent.click(screen.getByRole('button', { name: /analytics/i }));
    fireEvent.click(screen.getByRole('button', { name: /settings/i }));

    expect(screen.getByRole('heading', { level: 1, name: 'Dashboard' })).toBeInTheDocument();
    expect(screen.getByText('Operational insights for your team.')).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /settings/i })).toHaveAttribute('aria-current', 'page');
  });
});

