    render(
      <MetricCards
        metrics={[
          {
            id: 'revenue',
            label: 'Revenue',
            value: '$12,400',
            change: '+8.2%',
            trendDirection: 'up',
          },
          {
            id: 'churn',
            label: 'Churn',
            value: '2.1%',
            change: '-0.4%',
            trendDirection: 'down',
          },
        ]}
      />,
