  };
});

describe('ChartsSection', () => {
  it('renders both chart cards and chart content for valid datasets', () => {
    const trendData = [
      { label: 'Mon', value: 10, secondaryValue: 4, annotation: 'steady' },
      { label: 'Tue', value: 14, secondaryValue: 6, annotation: 'up' },
    ];

    const categoryData = [
      { id: 'a', label: 'Alpha', value: 30, color: '#111111', percentage: 60, detail: 'core' },
      { id: 'b', label: 'Beta', value: 20, color: '#222222', percentage: 40, detail: 'support' },
    ];

    render(<ChartsSection trendData={trendData} categoryData={categoryData} />);

    expect(
      screen.getByRole('region', {
        name: 'Charts overview section',
      }),
    ).toBeInTheDocument();

    expect(screen.getByText('7-Day Performance Trend')).toBeInTheDocument();
    expect(screen.getByText('Category Distribution')).toBeInTheDocument();
    expect(screen.getByTestId('line-chart')).toBeInTheDocument();
    expect(screen.getByTestId('bar-chart')).toBeInTheDocument();
    expect(screen.getAllByTestId('legend')).toHaveLength(2);

    const lineChartData = JSON.parse(screen.getByTestId('line-chart').getAttribute('data-chart-data') || '[]');
    expect(lineChartData).toEqual(trendData);

    const barChartData = JSON.parse(screen.getByTestId('bar-chart').getAttribute('data-chart-data') || '[]');
    expect(barChartData).toEqual(categoryData);
  });

  it('shows placeholder cards when datasets are missing', () => {
    render(<ChartsSection />);

    expect(
      screen.getByText(/Trend data is unavailable right now\. Add a seven-day dataset to display the line chart\./),
    ).toBeInTheDocument();
    expect(
      screen.getByText(/Category data is unavailable right now|category dataset/i),
    ).toBeInTheDocument();

    expect(screen.queryByTestId('line-chart')).not.toBeInTheDocument();
    expect(screen.queryByTestId('bar-chart')).not.toBeInTheDocument();
  });

  it('sanitizes invalid trend values and limits trend data to seven items', () => {
    const trendData = Array.from({ length: 8 }, (_, index) => ({
      label: `Day ${index + 1}`,
      value: index === 1 ? Number.NaN : index + 1,
      secondaryValue: index === 2 ? Number.POSITIVE_INFINITY : index + 10,
      annotation: index === 0 ? 'first' : undefined,
    }));

    const categoryData = [{ id: 'a', label: 'Alpha', value: 5, color: '#123456', percentage: 100, detail: '' }];

    render(<ChartsSection trendData={trendData} categoryData={categoryData} />);

    const lineChartData = JSON.parse(screen.getByTestId('line-chart').getAttribute('data-chart-data') || '[]');

    expect(lineChartData).toHaveLength(7);
    expect(lineChartData[1].value).toBe(0);
    expect(lineChartData[2].secondaryValue).toBe(0);
    expect(lineChartData[0].annotation).toBe('first');
    expect(lineChartData[6].label).toBe('Day 7');
  });
});

