import * as React from 'react';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, expect, it } from 'vitest';
import App from './App';
import { navigationItems } from './data/dashboardData';

describe('App', () => {
  it('renders the dashboard with the initially active navigation item content', () => {
    const initialItem = navigationItems.find((item) => item.isActive && item.id.trim().length > 0)
      ?? navigationItems.find((item) => item.id.trim().length > 0);

    if (!initialItem) {
      throw new Error('Expected at least one navigation item for App test setup');
    }

    render(<App />);

    expect(
      screen.getByRole('heading', { name: initialItem.label, level: 1 }),
    ).toBeInTheDocument();
    expect(screen.getByText(initialItem.description ?? 'Operational insights for your team.')).toBeInTheDocument();
    expect(
      screen.getByText(
        'All dashboard data is rendered locally with no routing, background sync, or network requests.',
      ),
    ).toBeInTheDocument();

    const activeNavButton = screen.getByRole('button', { name: new RegExp(initialItem.label, 'i') });
    expect(activeNavButton).toHaveAttribute('aria-current', 'page');
  });

  it('updates the header and active navigation when a different valid nav item is selected', async () => {
    const user = userEvent.setup();
    render(<App />);

    const targetItem =
      navigationItems.find((item) => item.id === 'analytics') ?? navigationItems.find((item) => !item.isActive);

    if (!targetItem) {
      throw new Error('Expected a secondary navigation item for App interaction test setup');
    }

    await user.click(screen.getByRole('button', { name: new RegExp(targetItem.label, 'i') }));

    expect(screen.getByRole('heading', { name: targetItem.label, level: 1 })).toBeInTheDocument();
    expect(
      screen.getByText(targetItem.description ?? 'Operational insights for your team.'),
    ).toBeInTheDocument();
    expect(screen.getByRole('button', { name: new RegExp(targetItem.label, 'i') })).toHaveAttribute(
      'aria-current',
      'page',
    );
  });

  it('falls back to generic header content when an unknown navigation id is submitted', async () => {
    const user = userEvent.setup();
    render(<App />);

    await user.click(screen.getByRole('button', { name: /settings/i }));

    const settingsButton = screen.getByRole('button', { name: /settings/i });
    expect(settingsButton).toHaveAttribute('aria-current', 'page');

    await user.click(settingsButton);

    expect(screen.getByRole('heading', { name: 'Settings', level: 1 })).toBeInTheDocument();
    expect(screen.getByText('Operational insights for your team.')).toBeInTheDocument();
  });
});

