import ChartsSection from './ChartsSection';

describe('ChartsSection', () => {
  it('renders both chart cards and chart content when trend and category data are provided', () => {
    render(
      <ChartsSection
        trendData={[
          { label: 'Mon', value: 12, secondaryValue: 7, annotation: 'up' },
          { label: 'Tue', value: 18, secondaryValue: 11, annotation: 'steady' },
        ]}
        categoryData={[
          { id: 'alpha', label: 'Alpha', value: 30, color: '#111827', percentage: 60, detail: 'Top segment' },
          { id: 'beta', label: 'Beta', value: 20, color: '#2563eb', percentage: 40, detail: 'Secondary' },
        ]}
      />,
    );

    expect(screen.getByRole('region', { name: 'Charts overview section' })).toBeInTheDocument();
    expect(screen.getByText('7-Day Performance Trend')).toBeInTheDocument();
    expect(screen.getByText('Category Distribution')).toBeInTheDocument();
    expect(screen.getByTestId('line-chart')).toHaveAttribute('data-points', '2');
    expect(screen.getByTestId('bar-chart')).toHaveAttribute('data-points', '2');
    expect(screen.getByText('Primary')).toBeInTheDocument();
    expect(screen.getByText('Secondary')).toBeInTheDocument();
  });

  it('shows placeholder content for both cards when datasets are missing', () => {
    render(<ChartsSection />);

    expect(
      screen.getByText(
        'Trend data is unavailable right now. Add a seven-day dataset to display the line chart.',
      ),
    ).toBeInTheDocument();
    expect(
      screen.getByText(
        'Category data is unavailable right now. Add distribution values to display the bar chart.',
      ),
    ).toBeInTheDocument();
    expect(screen.queryByTestId('line-chart')).not.toBeInTheDocument();
    expect(screen.queryByTestId('bar-chart')).not.toBeInTheDocument();
  });

  it('sanitizes invalid values and limits the trend chart to the latest seven entries', () => {
    render(
      <ChartsSection
        trendData={[
          { label: 'Day 1', value: 1, secondaryValue: 2, annotation: 'a' },
          { label: 'Day 2', value: 2, secondaryValue: 3, annotation: 'b' },
          { label: 'Day 3', value: 3, secondaryValue: 4, annotation: 'c' },
          { label: 'Day 4', value: 4, secondaryValue: 5, annotation: 'd' },
          { label: 'Day 5', value: 5, secondaryValue: 6, annotation: 'e' },
          { label: 'Day 6', value: 6, secondaryValue: 7, annotation: 'f' },
          { label: 'Day 7', value: 7, secondaryValue: 8, annotation: 'g' },
          { label: 'Day 8', value: Number.NaN, secondaryValue: Number.POSITIVE_INFINITY, annotation: 'h' },
        ]}
        categoryData={[
          { id: 'only', label: 'Only', value: Number.NaN, color: '#94a3b8', percentage: Number.NaN, detail: '' },
        ]}
      />,
    );

    expect(screen.getByTestId('line-chart')).toHaveAttribute('data-points', '7');
    expect(screen.getByTestId('bar-chart')).toHaveAttribute('data-points', '1');
  });
});

