import * as React from 'react';
import { render, screen } from '@testing-library/react';
import { describe, expect, it, vi } from 'vitest';

vi.mock('recharts', () => {
  const ResponsiveContainer = ({ children }: { children: React.ReactNode }) => (
    <div data-testid="responsive-container">{children}</div>
  );

  const LineChart = ({ data, children }: { data?: unknown[]; children?: React.ReactNode }) => (
    <div data-testid="line-chart" data-points={Array.isArray(data) ? data.length : 0}>
      {children}
    </div>
  );

  const BarChart = ({ data, children }: { data?: unknown[]; children?: React.ReactNode }) => (
    <div data-testid="bar-chart" data-points={Array.isArray(data) ? data.length : 0}>
      {children}
    </div>
  );

  const Line = ({ name }: { name?: string }) => <div>{name}</div>;
  const Bar = ({ dataKey }: { dataKey?: string }) => <div>{dataKey}</div>;
  const Primitive = () => <div />;
  const Cell = () => <div />;

  return {
    ResponsiveContainer,
    LineChart,
    BarChart,
    CartesianGrid: Primitive,
    XAxis: Primitive,
    YAxis: Primitive,
    Tooltip: Primitive,
    Legend: Primitive,
    Line,
    Bar,
    Cell,
  };
});

import ChartsSection from './ChartsSection';

