import * as React from 'react';
import { describe, expect, it } from 'vitest';
import { fireEvent, render, screen } from '@testing-library/react';
import '@testing-library/jest-dom';

import App from './App';
import { navigationItems } from './data/dashboardData';

describe('App', () => {
  it('renders the dashboard using the initially active navigation item and shared support copy', () => {
    const initialItem =
      navigationItems.find((item) => item.isActive === true && item.id.trim().length > 0) ??
      navigationItems.find((item) => item.id.trim().length > 0);

    render(<App />);

    expect(screen.getByRole('navigation', { name: 'Primary navigation' })).toBeInTheDocument();
    expect(screen.getByLabelText('Dashboard metrics')).toBeInTheDocument();
    expect(screen.getByLabelText('Dashboard insights')).toBeInTheDocument();

    if (initialItem) {
      expect(
        screen.getByRole('heading', { name: initialItem.label, level: 1 }),
      ).toBeInTheDocument();

      const selectedButton = screen.getByRole('button', { name: new RegExp(initialItem.label, 'i') });
      expect(selectedButton).toHaveAttribute('aria-pressed', 'true');
      expect(selectedButton).toHaveAttribute('aria-current', 'page');

      expect(
        screen.getByText(
          initialItem.description ?? 'Operational insights for your team.',
        ),
      ).toBeInTheDocument();
    }

    expect(
      screen.getByText(
        'All dashboard data is rendered locally with no routing, background sync, or network requests.',
      ),
    ).toBeInTheDocument();
  });

  it('updates the selected navigation item and header content when a different section is chosen', () => {
    const nextItem =
      navigationItems.find((item) => item.id === 'analytics') ??
      navigationItems.find((item) => item.id !== navigationItems[0]?.id && item.id.trim().length > 0);

    render(<App />);

    if (!nextItem) {
      throw new Error('Expected at least two navigation items for interaction test.');
    }

    fireEvent.click(screen.getByRole('button', { name: new RegExp(nextItem.label, 'i') }));

    expect(screen.getByRole('heading', { name: nextItem.label, level: 1 })).toBeInTheDocument();
    expect(
      screen.getByText(nextItem.description ?? 'Operational insights for your team.'),
    ).toBeInTheDocument();

    const selectedButton = screen.getByRole('button', { name: new RegExp(nextItem.label, 'i') });
    expect(selectedButton).toHaveAttribute('aria-pressed', 'true');
    expect(selectedButton).toHaveAttribute('aria-current', 'page');
  });

  it('falls back to default header copy when selecting a navigation id that is not in the seed data', () => {
    render(<App />);

    fireEvent.click(screen.getByRole('button', { name: /overview/i }));
    fireEvent.click(screen.getByRole('button', { name: /overview/i }));

    const sidebarButtons = screen.getAllByRole('button');
    expect(sidebarButtons.some((button) => button.getAttribute('aria-pressed') === 'true')).toBe(true);

    const sidebar = screen.getByRole('navigation', { name: 'Primary navigation' });
    const customEvent = new CustomEvent('select-invalid-nav', { detail: 'missing-section' });
    sidebar.dispatchEvent(customEvent);

    expect(
      screen.getByText(
        'All dashboard data is rendered locally with no routing, background sync, or network requests.',
      ),
    ).toBeInTheDocument();
  });
});

