    expect(screen.getByText('Secondary')).toBeInTheDocument();
    expect(screen.getByText('Total Value')).toBeInTheDocument();
    expect(screen.getByText('Mon:10:4:Launch')).toBeInTheDocument();
    expect(screen.getByText('Enterprise:38:38:Large accounts:#111111')).toBeInTheDocument();
