import { render, screen } from '@testing-library/react';
import { describe, expect, it, vi } from 'vitest';
import ChartsSection from './ChartsSection';
import type { CategoryChartData, TrendPoint } from '../data/dashboardData';

vi.mock('recharts', () => {
  const React = require('react');

  const getChildProps = (children: React.ReactNode, typeName: string) =>
    React.Children.toArray(children)
      .filter((child: unknown) => React.isValidElement(child) && (child.type as { displayName?: string })?.displayName === typeName)
      .map((child: unknown) => (React.isValidElement(child) ? child.props : null))
      .filter(Boolean);

  const ResponsiveContainer = ({ children }: { children: React.ReactNode }) => (
    <div data-testid="responsive-container">{children}</div>
  );

  const LineChart = ({ children, data }: { children: React.ReactNode; data: Array<Record<string, unknown>> }) => {
    const lineProps = getChildProps(children, 'Line');

    return (
      <div data-testid="line-chart" data-points={data?.length ?? 0}>
        {data?.map((point, index) => (
          <div key={`line-point-${index}`} data-testid="line-chart-point">
            {String(point.label)}:{String(point.value)}:{String(point.secondaryValue)}:{String(point.annotation ?? '')}
          </div>
        ))}
        {lineProps.map((props: Record<string, unknown>) => (
          <span key={String(props.dataKey)}>{String(props.name)}</span>
        ))}
        {children}
      </div>
    );
  };

  const BarChart = ({ children, data }: { children: React.ReactNode; data: Array<Record<string, unknown>> }) => {
    const barProps = getChildProps(children, 'Bar');

    return (
      <div data-testid="bar-chart" data-bars={data?.length ?? 0}>
        {data?.map((point, index) => (
          <div key={`bar-point-${index}`} data-testid="bar-chart-point">
            {String(point.label)}:{String(point.value)}:{String(point.percentage ?? '')}:{String(point.detail ?? '')}:{String(point.color)}
          </div>
        ))}
        {barProps.map((props: Record<string, unknown>) => (
          <span key={String(props.dataKey)}>{String(props.name)}</span>
        ))}
        {children}
      </div>
    );
  };

  const Line = (_props: unknown) => null;
  Line.displayName = 'Line';

  const Bar = ({ children }: { children?: React.ReactNode }) => <>{children}</>;
  Bar.displayName = 'Bar';

  const Cell = () => null;
  const CartesianGrid = () => null;
  const Legend = () => null;
  const Tooltip = () => null;
  const XAxis = () => null;
  const YAxis = () => null;

  return {
    ResponsiveContainer,
    LineChart,
    BarChart,
    Line,
    Bar,
    Cell,
    CartesianGrid,
    Legend,
    Tooltip,
    XAxis,
    YAxis,
  };
});

describe('ChartsSection', () => {
  it('renders both charts with provided trend and category data', () => {
    const trendData: TrendPoint[] = [
      { label: 'Mon', value: 10, secondaryValue: 4, annotation: 'Launch' },
      { label: 'Tue', value: 12, secondaryValue: 5 },
    ];
    const categoryData: CategoryChartData[] = [
      { id: 'a', label: 'Enterprise', value: 38, color: '#111111', percentage: 38, detail: 'Large accounts' },
      { id: 'b', label: 'SMB', value: 12, color: '#222222', percentage: 12, detail: 'Smaller accounts' },
    ];

    render(<ChartsSection trendData={trendData} categoryData={categoryData} />);

    expect(screen.getByLabelText('Charts overview section')).toBeInTheDocument();
    expect(screen.getByText('7-Day Performance Trend')).toBeInTheDocument();
    expect(screen.getByText('Category Distribution')).toBeInTheDocument();

    expect(screen.getByTestId('line-chart')).toHaveAttribute('data-points', '2');
    expect(screen.getByTestId('bar-chart')).toHaveAttribute('data-bars', '2');
    expect(screen.getByText('Primary')).toBeInTheDocument();
    expect(screen.getByText('Secondary')).toBeInTheDocument();
    expect(screen.getByText('Value')).toBeInTheDocument();
    expect(screen.getByText('Mon:10:4:Launch')).toBeInTheDocument();
    expect(screen.getByText('Enterprise:38:38:Large accounts:#111111')).toBeInTheDocument();
  });

  it('shows placeholder cards when datasets are missing', () => {
    render(<ChartsSection />);

    expect(
      screen.getByText(/Trend data is unavailable right now\. Add a seven-day dataset to display the line chart\./),
    ).toBeInTheDocument();
    expect(
      screen.getByText(/Category data is unavailable right now\. Add distribution data to display the chart\./),
    ).toBeInTheDocument();

    expect(screen.queryByTestId('line-chart')).not.toBeInTheDocument();
    expect(screen.queryByTestId('bar-chart')).not.toBeInTheDocument();
  });

  it('sanitizes invalid values and limits the trend chart to seven points', () => {
    const trendData = Array.from({ length: 8 }, (_, index) => ({
      label: index === 1 ? undefined : `Day ${index + 1}`,
      value: index === 2 ? Number.NaN : index + 1,
      secondaryValue: index === 3 ? Number.POSITIVE_INFINITY : index + 10,
      annotation: index === 4 ? undefined : `Note ${index + 1}`,
    })) as unknown as TrendPoint[];

    const categoryData = [
      {
        id: 'broken',
        label: undefined,
        value: Number.NaN,
        color: undefined,
        percentage: Number.POSITIVE_INFINITY,
        detail: undefined,
      },
    ] as unknown as CategoryChartData[];

    render(<ChartsSection trendData={trendData} categoryData={categoryData} />);

    const linePoints = screen.getAllByTestId('line-chart-point');
    expect(linePoints).toHaveLength(7);
    expect(screen.queryByText('Day 8:8:17:Note 8')).not.toBeInTheDocument();
    expect(screen.getByText('Day 2:2:11:Note 2')).toBeInTheDocument();
    expect(screen.getByText('Day 3:0:12:Note 3')).toBeInTheDocument();
    expect(screen.getByText('Day 4:4:0:Note 4')).toBeInTheDocument();
    expect(screen.getByText('Category 1:0:0::#94a3b8')).toBeInTheDocument();
  });
});

