}

interface SafeTrendDatum {
  label: string;
  value: number;
  secondaryValue: number;
  annotation: string;
}

interface SafeCategoryDatum {
  id: string;
  label: string;
  value: number;
  color: string;
  percentage: number;
  detail: string;
}

const sectionStyle: CSSProperties = {
