    expect(reportsButton).toHaveAttribute('aria-pressed', 'false');

    expect(screen.getByText('Summary metrics')).toBeInTheDocument();
    expect(screen.getByText('Critical issues')).toBeInTheDocument();
    expect(screen.getByLabelText('3 notifications')).toHaveTextContent('3');
    expect(screen.getByLabelText('0 notifications')).toHaveTextContent('0');
  });

  it('calls onSelect with the clicked item id', () => {
    const onSelect = vi.fn();

    render(
      <Sidebar items={items} selectedItemId="overview" onSelect={onSelect} />,
    );

    fireEvent.click(screen.getByRole('button', { name: /reports/i }));

    expect(onSelect).toHaveBeenCalledTimes(1);
    expect(onSelect).toHaveBeenCalledWith('reports');
  });

  it('falls back to the label for monograms and omits optional description and badge when absent', () => {
