import ChartsSection from './ChartsSection';
import type { CategoryChartData, TrendPoint } from '../data/dashboardData';

vi.mock('recharts', () => {
  const React = require('react');

  const getChildProps = (children: React.ReactNode, typeName: string) =>
    React.Children.toArray(children)
      .filter((child: unknown) => React.isValidElement(child) && (child.type as { displayName?: string })?.displayName === typeName)
      .map((child: unknown) => (React.isValidElement(child) ? child.props : null))
      .filter(Boolean);

  const ResponsiveContainer = ({ children }: { children: React.ReactNode }) => (
    <div data-testid="responsive-container">{children}</div>
  );

  const LineChart = ({ children, data }: { children: React.ReactNode; data: Array<Record<string, unknown>> }) => {
    const lineProps = getChildProps(children, 'Line');

    return (
      <div data-testid="line-chart" data-points={data?.length ?? 0}>
        {data?.map((point, index) => (
          <div key={`line-point-${index}`} data-testid="line-chart-point">
            {String(point.label)}:{String(point.value)}:{String(point.secondaryValue)}:{String(point.annotation ?? '')}
          </div>
        ))}
        {lineProps.map((props: Record<string, unknown>) => (
          <span key={String(props.dataKey)}>{String(props.name)}</span>
        ))}
        {children}
      </div>
    );
  };

  const BarChart = ({ children, data }: { children: React.ReactNode; data: Array<Record<string, unknown>> }) => {
    const barProps = getChildProps(children, 'Bar');

    return (
      <div data-testid="bar-chart" data-bars={data?.length ?? 0}>
        {data?.map((point, index) => (
          <div key={`bar-point-${index}`} data-testid="bar-chart-point">
            {String(point.label)}:{String(point.value)}:{String(point.percentage ?? '')}:{String(point.detail ?? '')}:{String(point.color)}
          </div>
        ))}
        {barProps.map((props: Record<string, unknown>) => (
          <span key={String(props.dataKey)}>{String(props.name)}</span>
        ))}
        {children}
      </div>
    );
  };

  const Line = (_props: unknown) => null;
  Line.displayName = 'Line';

  const Bar = ({ children }: { children?: React.ReactNode }) => <>{children}</>;
  Bar.displayName = 'Bar';

  const Cell = () => null;
  const CartesianGrid = () => null;
  const Legend = () => null;
  const Tooltip = () => null;
  const XAxis = () => null;
  const YAxis = () => null;

  return {
    ResponsiveContainer,
    LineChart,
    BarChart,
    Line,
    Bar,
    Cell,
    CartesianGrid,
    Legend,
    Tooltip,
    XAxis,
    YAxis,
  };
});

