  background: 'linear-gradient(180deg, #ffffff 0%, #f8fafc 100%)',
  boxShadow: '0 1px 2px rgba(15, 23, 42, 0.05)',
};

const headerRowStyle: React.CSSProperties = {
  display: 'flex',
  justifyContent: 'space-between',
  alignItems: 'flex-start',
  gap: '0.75rem',
  flexWrap: 'wrap',
};

const titleStyle: React.CSSProperties = {
  margin: 0,
  color: '#0f172a',
  fontSize: '1rem',
  fontWeight: 600,
  lineHeight: 1.4,
  flex: '1 1 220px',
};

const timeStyle: React.CSSProperties = {
  color: '#475569',
  fontSize: '0.85rem',
  whiteSpace: 'nowrap',
};

const detailStyle: React.CSSProperties = {
  margin: 0,
  color: '#334155',
  fontSize: '0.92rem',
  lineHeight: 1.5,
};

const metaStyle: React.CSSProperties = {
  display: 'flex',
  alignItems: 'center',
  gap: '0.5rem',
  flexWrap: 'wrap',
  color: '#64748b',
  fontSize: '0.82rem',
};

const badgeStyle: React.CSSProperties = {
  display: 'inline-flex',
  alignItems: 'center',
  padding: '0.2rem 0.55rem',
  borderRadius: '999px',
  backgroundColor: '#e2e8f0',
  color: '#334155',
  fontWeight: 600,
  textTransform: 'capitalize',
};

const FALLBACK_TITLE = 'Untitled activity';
const FALLBACK_DETAIL = 'Status unavailable';
const FALLBACK_TIME = 'Time unavailable';

const formatTimestamp = (timestamp?: string): string => {
  if (!timestamp) {
    return FALLBACK_TIME;
  }

  const date = new Date(timestamp);

  if (Number.isNaN(date.getTime())) {
    return FALLBACK_TIME;
  }

  return new Intl.DateTimeFormat(undefined, {
    dateStyle: 'medium',
    timeStyle: 'short',
  }).format(date);
};

const getTimestampValue = (timestamp?: string): number => {
  if (!timestamp) {
    return Number.NEGATIVE_INFINITY;
  }

  const timeValue = new Date(timestamp).getTime();
  return Number.isNaN(timeValue) ? Number.NEGATIVE_INFINITY : timeValue;
};

const getActivityDetail = (item: Partial<ActivityItem>): string => {
  const description = typeof item.description === 'string' ? item.description.trim() : '';
  if (description) {
    return description;
  }

  const status = typeof item.status === 'string' ? item.status.replace(/-/g, ' ').trim() : '';
  if (status) {
    return status.charAt(0).toUpperCase() + status.slice(1);
  }

  return FALLBACK_DETAIL;
};

const RecentActivity = ({ items }: RecentActivityProps): React.JSX.Element => {
  const sortedItems = useMemo(() => {
    if (!Array.isArray(items)) {
      return [];
    }

    return [...items].sort((firstItem, secondItem) => {
      return getTimestampValue(secondItem?.timestamp) - getTimestampValue(firstItem?.timestamp);
    });
  }, [items]);

  if (sortedItems.length === 0) {
    return (
      <section style={containerStyle} aria-live="polite">
        <p style={emptyStateStyle}>No recent activity</p>
      </section>
    );
  }

  return (
    <section style={containerStyle} aria-label="Recent activity">
      <ul style={listStyle}>
        {sortedItems.map((item, index) => {
          const safeTitle = typeof item?.title === 'string' && item.title.trim() ? item.title : FALLBACK_TITLE;
          const safeTime = formatTimestamp(item?.timestamp);
          const detail = getActivityDetail(item ?? {});
          const statusLabel = typeof item?.status === 'string' && item.status.trim()
            ? item.status.replace(/-/g, ' ')
            : undefined;
          const key = typeof item?.id === 'string' && item.id.trim() ? item.id : `activity-${index}`;

          return (
            <li key={key} style={itemStyle}>
              <div style={headerRowStyle}>
                <h3 style={titleStyle}>{safeTitle}</h3>
                <time style={timeStyle} dateTime={typeof item?.timestamp === 'string' ? item.timestamp : undefined}>
                  {safeTime}
                </time>
              </div>

              <p style={detailStyle}>{detail}</p>

              {(statusLabel || item?.category || item?.userName) && (
                <div style={metaStyle}>
                  {statusLabel && <span style={badgeStyle}>{statusLabel}</span>}
                  {item?.category && <span>{item.category}</span>}
                  {item?.userName && <span>{item.userName}</span>}
                </div>
              )}
            </li>
          );
        })}
      </ul>
    </section>
  );
};

export default RecentActivity;

import * as React from 'react';

/** Props for the DashboardLayout component. */
export interface DashboardLayoutProps {
  /** Sidebar content rendered alongside the main dashboard area on desktop screens. */
  sidebar: React.ReactNode;
  /** Optional header content rendered at the top of the main content column. */
  header?: React.ReactNode;
  /** Metrics content rendered first inside the main content area. */
  metrics: React.ReactNode;
  /** Charts content rendered in the responsive secondary grid. */
  charts: React.ReactNode;
  /** Activity content rendered beside charts on larger screens and below on smaller screens. */
  activity: React.ReactNode;
  /** Optional additional class name for the outermost layout container. */
  className?: string;
}

const getContainerClasses = (className?: string): string => {
  const baseClasses = [
    'min-h-screen',
    'w-full',
    'overflow-x-hidden',
    'bg-slate-100',
    'text-slate-900',
    'lg:flex',
    'lg:items-stretch',
  ];

  if (typeof className === 'string' && className.trim()) {
    baseClasses.push(className.trim());
  }

  return baseClasses.join(' ');
};

/**
 * Provides a responsive dashboard shell with a sidebar and main content area.
 *
 * The main content is ordered as header, metrics, then a responsive charts/activity
 * grid that collapses to a single column on smaller screens while preserving
 * min-width safeguards to prevent horizontal overflow.
 */
export function DashboardLayout({
  sidebar,
  header,
  metrics,
  charts,
  activity,
  className,
}: DashboardLayoutProps): React.JSX.Element {
  return (
    <div className={getContainerClasses(className)}>
      <div className="min-w-0 shrink-0 lg:w-72 lg:max-w-[18rem] lg:basis-72">
        {sidebar}
      </div>

      <main className="min-w-0 flex-1 overflow-x-hidden">
        <div className="mx-auto flex min-w-0 w-full max-w-screen-2xl flex-col gap-6 px-4 py-4 sm:gap-6 sm:px-6 sm:py-6 lg:px-8 lg:py-8 xl:px-10">
          {header ? <div className="min-w-0">{header}</div> : null}

          <section className="min-w-0" aria-label="Dashboard metrics">
            {metrics}
          </section>

          <section
            className="grid min-w-0 grid-cols-1 gap-6 xl:grid-cols-[minmax(0,1.65fr)_minmax(0,1fr)]"
            aria-label="Dashboard insights"
          >
            <div className="min-w-0 overflow-hidden">
              {charts}
            </div>

            <div className="min-w-0 overflow-hidden">
              {activity}
            </div>
          </section>
        </div>
      </main>
    </div>
  );
}

export default DashboardLayout;

import * as React from 'react';
import { DashboardLayout } from './components/DashboardLayout';
import { Header } from './components/Header';
import { MetricCards } from './components/MetricCards';
import ChartsSection from './components/ChartsSection';
import RecentActivity from './components/RecentActivity';
import { Sidebar } from './components/Sidebar';
import {
  activityItems,
  categoryDistributionData,
  metrics,
  navigationItems,
  trendData,
  type NavigationItem,
} from './data/dashboardData';

/** Header copy derived from the selected dashboard navigation item. */
interface HeaderContent {
  /** Primary page title shown in the dashboard header. */
  title: string;
  /** Supporting description for the currently selected section. */
  subtitle: string;
  /** Additional static context shown with the header. */
  supportInfo: string;
}

/**
 * Builds navigation data with the selected item marked as active.
 */
function buildNavigationItems(selectedNavId: string): NavigationItem[] {
  const normalizedSelectedNavId: string = selectedNavId.trim();
  const hasSelectedMatch: boolean = navigationItems.some(
    (item: NavigationItem): boolean => item.id === normalizedSelectedNavId,
  );

  return navigationItems.map(
    (item: NavigationItem): NavigationItem => ({
      ...item,
      isActive: hasSelectedMatch
        ? item.id === normalizedSelectedNavId
        : item.isActive === true,
    }),
  );
}

/**
 * Returns the initial selected navigation id from the local dashboard seed data.
 */
function getInitialSelectedNavId(): string {
  const activeItem: NavigationItem | undefined = navigationItems.find(
    (item: NavigationItem): boolean => item.isActive === true && item.id.trim().length > 0,
  );

  if (activeItem) {
    return activeItem.id;
  }

  const firstValidItem: NavigationItem | undefined = navigationItems.find(
    (item: NavigationItem): boolean => item.id.trim().length > 0,
  );

  return firstValidItem ? firstValidItem.id : '';
}

/**
 * Returns presentation copy for the current dashboard section.
 */
function getHeaderContent(selectedNavId: string): HeaderContent {
  const normalizedSelectedNavId: string = selectedNavId.trim();
  const selectedItem: NavigationItem | undefined = navigationItems.find(
    (item: NavigationItem): boolean => item.id === normalizedSelectedNavId,
  );

  const label: string = selectedItem?.label ?? 'Dashboard';
  const description: string =
    selectedItem?.description ?? 'Operational insights for your team.';

  return {
    title: label,
    subtitle: description,
    supportInfo:
      'All dashboard data is rendered locally with no routing, background sync, or network requests.',
  };
}

/**
 * App renders the single dashboard page and keeps all interaction state local.
 */
export default function App(): React.JSX.Element {
  const [selectedNavId, setSelectedNavId] = React.useState<string>(getInitialSelectedNavId);

  const selectedNavigationItems: NavigationItem[] = React.useMemo(
    (): NavigationItem[] => buildNavigationItems(selectedNavId),
    [selectedNavId],
  );

  const headerContent: HeaderContent = React.useMemo(
    (): HeaderContent => getHeaderContent(selectedNavId),
    [selectedNavId],
  );

  const handleNavigationSelect = React.useCallback((itemId: string): void => {
    const normalizedItemId: string = itemId.trim();

    if (!normalizedItemId) {
      return;
    }

    setSelectedNavId(normalizedItemId);
  }, []);

  return (
    <DashboardLayout
      sidebar={
        <Sidebar
          items={selectedNavigationItems}
          selectedItemId={selectedNavId}
          onSelect={handleNavigationSelect}
        />
      }
      header={
        <Header
          title={headerContent.title}
          subtitle={headerContent.subtitle}
          supportInfo={headerContent.supportInfo}
        />
      }
      metrics={<MetricCards metrics={metrics} />}
      charts={<ChartsSection trendData={trendData} categoryData={categoryDistributionData} />}
      activity={<RecentActivity items={activityItems} />}
    />
  );
}

