import { describe, expect, it } from 'vitest';

import {
  activityItems,
  categoryDistributionData,
  metrics,
  navigationItems,
  trendData,
} from './dashboardData';

describe('dashboardData', () => {
  it('exports the expected dashboard collections for the happy path', () => {
    expect(navigationItems).toHaveLength(5);
    expect(metrics).toHaveLength(3);
    expect(trendData).toHaveLength(7);
    expect(categoryDistributionData).toHaveLength(4);
    expect(activityItems).toHaveLength(6);

    expect(navigationItems[0]).toMatchObject({
      id: 'overview',
      label: 'Overview',
      href: '#overview',
      isActive: true,
    });

    expect(metrics[0]).toMatchObject({
      id: 'monthly-revenue',
      value: '$184,200',
      change: '+12.4%',
      trendDirection: 'up',
    });

    expect(trendData[2]).toMatchObject({
      label: 'Wed',
      value: 51,
      secondaryValue: 45,
      annotation: 'Campaign launch',
    });

    expect(categoryDistributionData[0]).toMatchObject({
      id: 'enterprise',
      value: 38,
      percentage: 38,
    });

    expect(activityItems[0]).toMatchObject({
      id: 'act-001',
      status: 'completed',
      userName: 'Alicia Chen',
    });
  });

  it('marks only the overview navigation item as active and keeps ids unique', () => {
    const activeItems = navigationItems.filter((item) => item.isActive);
    expect(activeItems).toHaveLength(1);
    expect(activeItems[0]?.id).toBe('overview');

    const ids = navigationItems.map((item) => item.id);
    expect(new Set(ids).size).toBe(ids.length);
  });

  it('captures important edge-case data shapes across collections', () => {
    const supportResolutionMetric = metrics.find((metric) => metric.id === 'support-resolution');
    expect(supportResolutionMetric).toMatchObject({
      change: '-9.8%',
      trendDirection: 'down',
      helperText: 'Lower is better',
    });

    const weekendTrend = trendData.find((point) => point.label === 'Sun');
    expect(weekendTrend).toMatchObject({
      annotation: 'Weekend dip in signups',
      secondaryValue: 46,
    });

    const totalPercentage = categoryDistributionData.reduce(
      (sum, item) => sum + (item.percentage ?? 0),
      0,
    );
    expect(totalPercentage).toBe(100);

    expect(activityItems.some((item) => item.status === 'flagged')).toBe(true);
    expect(activityItems.some((item) => item.userName === undefined)).toBe(true);
  });
});

import * as React from 'react';
import { describe, expect, it, vi } from 'vitest';
import { fireEvent, render, screen } from '@testing-library/react';
import { Sidebar } from './Sidebar';
