describe('Sidebar', () => {
  const items: NavigationItem[] = [
    {
      id: 'overview',
      label: 'Overview',
      description: 'Summary metrics',
      icon: 'ov',
      badgeCount: 3,
    },
    {
      id: 'alerts',
      label: 'Alerts',
      description: 'Critical issues',
      badgeCount: 0,
    },
    {
      id: 'reports',
      label: 'Reports',
      icon: 'r',
    },
  ];

  it('renders navigation items and marks the selected item as current', () => {
    render(
      <Sidebar items={items} selectedItemId="alerts" onSelect={vi.fn()} />,
    );

    expect(screen.getByText('DataScope')).toBeInTheDocument();
    expect(
      screen.getByRole('navigation', { name: 'Primary navigation' }),
    ).toBeInTheDocument();

    const overviewButton = screen.getByRole('button', { name: /overview/i });
    const alertsButton = screen.getByRole('button', { name: /alerts/i });
    const reportsButton = screen.getByRole('button', { name: /reports/i });

    expect(overviewButton).toHaveAttribute('aria-pressed', 'false');
    expect(overviewButton).not.toHaveAttribute('aria-current');

    expect(alertsButton).toHaveAttribute('aria-pressed', 'true');
    expect(alertsButton).toHaveAttribute('aria-current', 'page');

    expect(reportsButton).toHaveAttribute('aria-pressed', 'false');

    expect(screen.getByText('Summary metrics')).toBeInTheDocument();
    expect(screen.getByText('Critical issues')).toBeInTheDocument();
    expect(screen.getByLabelText('3 notifications')).toHaveTextContent('3');
    expect(screen.getByLabelText('0 notifications')).toHaveTextContent('0');
