    const { container } = render(
      <Sidebar
        items={edgeCaseItems}
        selectedItemId="sales"
        onSelect={vi.fn()}
      />,
    );

    expect(screen.getByRole('button', { name: /sales/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Q' })).toBeInTheDocument();
    expect(container).toHaveTextContent('SA');
    expect(container).toHaveTextContent('Q');
    expect(screen.queryByLabelText(/notifications/i)).not.toBeInTheDocument();
  });
});

