import * as React from 'react';
import { render, screen } from '@testing-library/react';
import { describe, expect, it, vi } from 'vitest';
import ChartsSection from './ChartsSection';

vi.mock('recharts', () => {
  const React = require('react');

  const createComponent = (name: string) => {
    const Component = ({ children, ...props }: any) =>
      React.createElement(
        'div',
        {
          'data-testid': name,
          ...Object.fromEntries(
            Object.entries(props).map(([key, value]) => [
              `data-prop-${key}`,
              typeof value === 'object' ? JSON.stringify(value) : String(value),
            ]),
          ),
        },
        children,
      );
    Component.displayName = name;
    return Component;
  };

  return {
    ResponsiveContainer: createComponent('ResponsiveContainer'),
    LineChart: createComponent('LineChart'),
    BarChart: createComponent('BarChart'),
    CartesianGrid: createComponent('CartesianGrid'),
    XAxis: createComponent('XAxis'),
    YAxis: createComponent('YAxis'),
    Tooltip: createComponent('Tooltip'),
    Legend: createComponent('Legend'),
    Line: createComponent('Line'),
    Bar: createComponent('Bar'),
    Cell: createComponent('Cell'),
  };
});

describe('ChartsSection', () => {
  it('renders both chart cards with chart content when trend and category data are provided', () => {
    render(
      <ChartsSection
        trendData={[
          { label: 'Mon', value: 10, secondaryValue: 5, annotation: 'steady' },
          { label: 'Tue', value: 12, secondaryValue: 6, annotation: 'up' },
        ]}
        categoryData={[
          { id: 'a', label: 'Alpha', value: 40, color: '#ff0000', percentage: 40, detail: 'core' },
          { id: 'b', label: 'Beta', value: 60, color: '#00ff00', percentage: 60, detail: 'growth' },
        ]}
      />,
    );

    expect(screen.getByRole('region', { name: 'Charts overview section' })).toBeInTheDocument();
    expect(screen.getByText('7-Day Performance Trend')).toBeInTheDocument();
    expect(screen.getByText('Category Distribution')).toBeInTheDocument();

    expect(screen.getByTestId('LineChart')).toBeInTheDocument();
    expect(screen.getByTestId('BarChart')).toBeInTheDocument();
    expect(screen.getByText('Primary')).toBeInTheDocument();
    expect(screen.getByText('Secondary')).toBeInTheDocument();
  });

  it('renders placeholder messages when both datasets are missing', () => {
    render(<ChartsSection />);

    expect(
      screen.getByText(
        'Trend data is unavailable right now. Add a seven-day dataset to display the line chart.',
      ),
    ).toBeInTheDocument();
    expect(
      screen.getByText(
        'Category data is unavailable right now. Add distribution values to display the bar chart.',
      ),
    ).toBeInTheDocument();

    expect(screen.queryByTestId('LineChart')).not.toBeInTheDocument();
    expect(screen.queryByTestId('BarChart')).not.toBeInTheDocument();
  });

  it('sanitizes invalid trend values and limits trend data to seven points', () => {
    const trendData = Array.from({ length: 8 }, (_, index) => ({
      label: `Day ${index + 1}`,
      value: index === 1 ? Number.NaN : index + 1,
      secondaryValue: index === 2 ? Number.POSITIVE_INFINITY : index + 2,
      annotation: index === 0 ? 'note' : '',
    }));

    render(
