    ).not.toBeInTheDocument();
  });

  it('renders placeholder messages when both datasets are missing', () => {
    render(<ChartsSection />);

    expect(
      screen.getByText(/Trend data is unavailable right now\. Add a seven-day dataset to display the line chart\./i),
    ).toBeInTheDocument();
    expect(screen.queryByTestId('line-chart')).not.toBeInTheDocument();

    expect(screen.getByText(/Category data is unavailable right now/i)).toBeInTheDocument();
    expect(screen.queryByTestId('bar-chart')).not.toBeInTheDocument();
  });

  it('handles partial data by showing the available chart and the missing-data placeholder', () => {
    render(
      <ChartsSection
        trendData={[{ label: 'Wed', value: 8, secondaryValue: 2, annotation: 'ok' }]}
        categoryData={[]}
      />,
    );

    expect(screen.getByTestId('line-chart')).toBeInTheDocument();
    expect(screen.queryByText(/Trend data is unavailable right now/i)).not.toBeInTheDocument();

    expect(screen.queryByTestId('bar-chart')).not.toBeInTheDocument();
    expect(screen.getByText(/Category data is unavailable right now/i)).toBeInTheDocument();
  });
});

