import * as React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import '@testing-library/jest-dom';
import { describe, expect, it } from 'vitest';

import App from './App';
import { navigationItems } from './data/dashboardData';

describe('App', () => {
  it('renders the dashboard using the initial active navigation item and core sections', () => {
    const initialItem =
      navigationItems.find((item) => item.isActive === true && item.id.trim().length > 0) ??
      navigationItems.find((item) => item.id.trim().length > 0);

    render(<App />);

    expect(
      screen.getByRole('navigation', { name: 'Primary navigation' }),
    ).toBeInTheDocument();

    expect(
      screen.getByRole('heading', { name: initialItem?.label ?? 'Dashboard', level: 1 }),
    ).toBeInTheDocument();

    expect(
      screen.getByText(
        initialItem?.description ?? 'Operational insights for your team.',
      ),
    ).toBeInTheDocument();

    expect(
      screen.getByText(
        'All dashboard data is rendered locally with no routing, background sync, or network requests.',
      ),
    ).toBeInTheDocument();

    expect(screen.getByLabelText('Dashboard metrics')).toBeInTheDocument();
    expect(screen.getByLabelText('Dashboard insights')).toBeInTheDocument();
  });

  it('updates the selected section header and active navigation state when a navigation item is clicked', () => {
    render(<App />);

    fireEvent.click(screen.getByRole('button', { name: /analytics/i }));

    expect(
      screen.getByRole('heading', { name: 'Analytics', level: 1 }),
    ).toBeInTheDocument();
    expect(
      screen.getByText('Performance trends and funnel insights'),
    ).toBeInTheDocument();

    expect(screen.getByRole('button', { name: /analytics/i })).toHaveAttribute(
      'aria-current',
      'page',
    );
    expect(screen.getByRole('button', { name: /analytics/i })).toHaveAttribute(
      'aria-pressed',
      'true',
    );
    expect(screen.getByRole('button', { name: /overview/i })).toHaveAttribute(
      'aria-pressed',
      'false',
    );
  });

  it('uses fallback header copy for navigation items without a description', () => {
    render(<App />);

    fireEvent.click(screen.getByRole('button', { name: /operations/i }));

    expect(
      screen.getByRole('heading', { name: 'Operations', level: 1 }),
    ).toBeInTheDocument();
    expect(
      screen.getByText('Operational insights for your team.'),
    ).toBeInTheDocument();
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

const MAIN_MODULE_PATH = './main';

describe('src/main', () => {
  beforeEach(() => {
    vi.resetModules();
    vi.unmock('./App');
    vi.unmock('react-dom/client');
    document.body.innerHTML = '';
  });

  afterEach(() => {
    document.body.innerHTML = '';
    vi.clearAllMocks();
  });

  it('creates a React root on #root and renders App inside StrictMode', async () => {
    document.body.innerHTML = '<div id="root"></div>';

    const render = vi.fn();
    const createRoot = vi.fn(() => ({ render }));

    vi.doMock('./App', () => ({
      default: () => <div data-testid="app">Mock App</div>,
    }));

    vi.doMock('react-dom/client', () => ({
      createRoot,
    }));

    const React = await import('react');

    await import(MAIN_MODULE_PATH);

    const rootElement = document.getElementById('root');
    expect(createRoot).toHaveBeenCalledTimes(1);
    expect(createRoot).toHaveBeenCalledWith(rootElement);
    expect(render).toHaveBeenCalledTimes(1);

    const renderedTree = render.mock.calls[0][0];
    expect(renderedTree.type).toBe(React.StrictMode);
    expect(renderedTree.props.children.type).toBeTypeOf('function');
  });

  it('renders the App component as the child of StrictMode', async () => {
    document.body.innerHTML = '<div id="root"></div>';

    const render = vi.fn();
    const mockedApp = vi.fn(() => <div>Mock App</div>);

    vi.doMock('./App', () => ({
      default: mockedApp,
    }));

    vi.doMock('react-dom/client', () => ({
      createRoot: vi.fn(() => ({ render })),
    }));

    await import(MAIN_MODULE_PATH);

