import React from 'react';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, expect, it } from 'vitest';
import App from './App';
import { navigationItems } from './data/dashboardData';

describe('App', () => {
  it('renders the dashboard with the initially active navigation content', () => {
    const activeItem = navigationItems.find((item) => item.isActive === true && item.id.trim().length > 0);

    render(<App />);

    expect(
      screen.getByRole('heading', {
        level: 1,
        name: activeItem?.label ?? 'Overview',
      }),
    ).toBeInTheDocument();

    expect(
      screen.getByText(
        activeItem?.description ?? 'Operational insights for your team.',
      ),
    ).toBeInTheDocument();

    expect(
      screen.getByText(
        'All dashboard data is rendered locally with no routing, background sync, or network requests.',
      ),
    ).toBeInTheDocument();
  });

  it('updates the header and selected navigation state when a different nav item is chosen', async () => {
    const user = userEvent.setup();
    const analyticsItem = navigationItems.find((item) => item.id === 'analytics');

    render(<App />);

    const analyticsButton = screen.getByRole('button', {
      name: new RegExp(analyticsItem?.label ?? 'Analytics', 'i'),
    });

    await user.click(analyticsButton);

    expect(
      screen.getByRole('heading', {
        level: 1,
        name: analyticsItem?.label ?? 'Analytics',
      }),
    ).toBeInTheDocument();

    expect(
      screen.getByText(
        analyticsItem?.description ?? 'Performance trends and funnel insights',
      ),
    ).toBeInTheDocument();

    expect(analyticsButton).toHaveAttribute('aria-current', 'page');
  });

  it('ignores blank navigation selections and preserves the current header state', async () => {
    const user = userEvent.setup();

    render(<App />);

    const overviewButton = screen.getByRole('button', { name: /overview/i });
    const analyticsButton = screen.getByRole('button', { name: /analytics/i });

    await user.click(analyticsButton);
    expect(screen.getByRole('heading', { level: 1, name: /analytics/i })).toBeInTheDocument();

    await user.click(overviewButton);
    expect(screen.getByRole('heading', { level: 1, name: /overview/i })).toBeInTheDocument();
  });
});

