interface HeaderContent {
  /** Primary page title shown in the dashboard header. */
  title: string;
  /** Supporting description for the currently selected section. */
  subtitle: string;
  /** Additional static context shown with the header. */
  supportInfo: string;
}

/**
 * Builds navigation data with the selected item marked as active.
 */
function buildNavigationItems(selectedNavId: string): NavigationItem[] {
  const normalizedSelectedNavId: string = selectedNavId.trim();
  const hasSelectedMatch: boolean = navigationItems.some(
    (item: NavigationItem): boolean => item.id === normalizedSelectedNavId,
  );

  return navigationItems.map(
    (item: NavigationItem): NavigationItem => ({
      ...item,
      isActive: hasSelectedMatch
        ? item.id === normalizedSelectedNavId
        : item.isActive === true,
    }),
  );
}

/**
 * Returns the initial selected navigation id from the local dashboard seed data.
 */
function getInitialSelectedNavId(): string {
  const activeItem: NavigationItem | undefined = navigationItems.find(
    (item: NavigationItem): boolean => item.isActive === true && item.id.trim().length > 0,
  );

  if (activeItem) {
    return activeItem.id;
  }

  const firstValidItem: NavigationItem | undefined = navigationItems.find(
    (item: NavigationItem): boolean => item.id.trim().length > 0,
  );

  return firstValidItem ? firstValidItem.id : '';
}

/**
 * Returns presentation copy for the current dashboard section.
 */
function getHeaderContent(selectedNavId: string): HeaderContent {
  const normalizedSelectedNavId: string = selectedNavId.trim();
  const selectedItem: NavigationItem | undefined = navigationItems.find(
    (item: NavigationItem): boolean => item.id === normalizedSelectedNavId,
  );

  const label: string = selectedItem?.label ?? 'Dashboard';
  const description: string =
    selectedItem?.description ?? 'Operational insights for your team.';

  return {
    title: label,
    subtitle: description,
    supportInfo:
      'All dashboard data is rendered locally with no routing, background sync, or network requests.',
  };
}

/**
 * App renders the single dashboard page and keeps all interaction state local.
 */
export default function App(): React.JSX.Element {
  const [selectedNavId, setSelectedNavId] = React.useState<string>(getInitialSelectedNavId);

  const selectedNavigationItems: NavigationItem[] = React.useMemo(
    (): NavigationItem[] => buildNavigationItems(selectedNavId),
    [selectedNavId],
  );

  const headerContent: HeaderContent = React.useMemo(
    (): HeaderContent => getHeaderContent(selectedNavId),
    [selectedNavId],
  );

  const handleNavigationSelect = React.useCallback((itemId: string): void => {
    const normalizedItemId: string = itemId.trim();

    if (!normalizedItemId) {
      return;
    }

    setSelectedNavId(normalizedItemId);
  }, []);

  return (
    <DashboardLayout
      sidebar={
        <Sidebar
          items={selectedNavigationItems}
          selectedItemId={selectedNavId}
          onSelect={handleNavigationSelect}
        />
      }
      header={
        <Header
          title={headerContent.title}
          subtitle={headerContent.subtitle}
          supportInfo={headerContent.supportInfo}
        />
      }
      metrics={<MetricCards metrics={metrics} />}
      charts={<ChartsSection trendData={trendData} categoryData={categoryDistributionData} />}
      activity={<RecentActivity items={activityItems} />}
    />
  );
}

import * as React from 'react';
import * as ReactDOM from 'react-dom/client';
import App from './App';
import './index.css';

const rootElement: HTMLElement | null = document.getElementById('root');

if (rootElement === null) {
  throw new Error('Root element with id "root" was not found.');
}

ReactDOM.createRoot(rootElement).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>,
);

import { describe, expect, it } from 'vitest';

import {
  activityItems,
  categoryDistributionData,
  metrics,
  navigationItems,
  trendData,
} from './dashboardData';

describe('dashboardData', () => {
  it('exports the expected dashboard collections for the happy path', () => {
    expect(navigationItems).toHaveLength(5);
    expect(metrics).toHaveLength(3);
    expect(trendData).toHaveLength(7);
    expect(categoryDistributionData).toHaveLength(4);
    expect(activityItems).toHaveLength(6);

    expect(navigationItems[0]).toMatchObject({
      id: 'overview',
      label: 'Overview',
      href: '#overview',
      isActive: true,
    });

    expect(metrics[0]).toMatchObject({
      id: 'monthly-revenue',
      value: '$184,200',
      change: '+12.4%',
      trendDirection: 'up',
    });

    expect(trendData[2]).toMatchObject({
      label: 'Wed',
      value: 51,
      secondaryValue: 45,
      annotation: 'Campaign launch',
    });

    expect(categoryDistributionData[0]).toMatchObject({
      id: 'enterprise',
      value: 38,
      percentage: 38,
    });

    expect(activityItems[0]).toMatchObject({
      id: 'act-001',
      status: 'completed',
      userName: 'Alicia Chen',
    });
  });

  it('marks only the overview navigation item as active and keeps ids unique', () => {
    const activeItems = navigationItems.filter((item) => item.isActive);
    expect(activeItems).toHaveLength(1);
    expect(activeItems[0]?.id).toBe('overview');

    const ids = navigationItems.map((item) => item.id);
    expect(new Set(ids).size).toBe(ids.length);
  });

  it('captures important edge-case data shapes across collections', () => {
    const supportResolutionMetric = metrics.find((metric) => metric.id === 'support-resolution');
    expect(supportResolutionMetric).toMatchObject({
      change: '-9.8%',
      trendDirection: 'down',
      helperText: 'Lower is better',
    });

    const weekendTrend = trendData.find((point) => point.label === 'Sun');
    expect(weekendTrend).toMatchObject({
      annotation: 'Weekend dip in signups',
      secondaryValue: 46,
    });

    const totalPercentage = categoryDistributionData.reduce(
      (sum, item) => sum + (item.percentage ?? 0),
      0,
    );
    expect(totalPercentage).toBe(100);

    expect(activityItems.some((item) => item.status === 'flagged')).toBe(true);
    expect(activityItems.some((item) => item.userName === undefined)).toBe(true);
  });
});

import * as React from 'react';
import { describe, expect, it, vi } from 'vitest';
import { fireEvent, render, screen } from '@testing-library/react';
import { Sidebar } from './Sidebar';
import type { NavigationItem } from '../data/dashboardData';

describe('Sidebar', () => {
  const items: NavigationItem[] = [
    {
      id: 'overview',
      label: 'Overview',
      description: 'Summary metrics',
      icon: 'ov',
      badgeCount: 3,
    },
    {
      id: 'alerts',
      label: 'Alerts',
      description: 'Critical issues',
      badgeCount: 0,
    },
    {
      id: 'reports',
      label: 'Reports',
      icon: 'r',
    },
  ];

  it('renders navigation items and marks the selected item as current', () => {
    render(
      <Sidebar items={items} selectedItemId="alerts" onSelect={vi.fn()} />,
    );

    expect(screen.getByText('DataScope')).toBeInTheDocument();
    expect(
      screen.getByRole('navigation', { name: 'Primary navigation' }),
    ).toBeInTheDocument();

    const overviewButton = screen.getByRole('button', { name: /overview/i });
    const alertsButton = screen.getByRole('button', { name: /alerts/i });
    const reportsButton = screen.getByRole('button', { name: /reports/i });

    expect(overviewButton).toHaveAttribute('aria-pressed', 'false');
    expect(overviewButton).not.toHaveAttribute('aria-current');

    expect(alertsButton).toHaveAttribute('aria-pressed', 'true');
    expect(alertsButton).toHaveAttribute('aria-current', 'page');

    expect(reportsButton).toHaveAttribute('aria-pressed', 'false');

    expect(screen.getByText('Summary metrics')).toBeInTheDocument();
    expect(screen.getByText('Critical issues')).toBeInTheDocument();
    expect(screen.getByLabelText('3 notifications')).toHaveTextContent('3');
    expect(screen.getByLabelText('0 notifications')).toHaveTextContent('0');
  });

  it('calls onSelect with the clicked item id', () => {
    const onSelect = vi.fn();

    render(
      <Sidebar items={items} selectedItemId="overview" onSelect={onSelect} />,
    );

    fireEvent.click(screen.getByRole('button', { name: /reports/i }));

    expect(onSelect).toHaveBeenCalledTimes(1);
    expect(onSelect).toHaveBeenCalledWith('reports');
  });

  it('falls back to the label for monograms and omits optional description and badge when absent', () => {
    const edgeCaseItems: NavigationItem[] = [
      {
        id: 'sales',
        label: ' Sales ',
        icon: '   ',
      },
      {
        id: 'qa',
        label: 'Q',
      },
    ];

    const { container } = render(
      <Sidebar
        items={edgeCaseItems}
        selectedItemId="sales"
        onSelect={vi.fn()}
      />,
    );

    expect(screen.getByRole('button', { name: /sales/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Q' })).toBeInTheDocument();
    expect(container).toHaveTextContent('SA');
    expect(container).toHaveTextContent('Q');
    expect(screen.queryByLabelText(/notifications/i)).not.toBeInTheDocument();
  });
});

