    ).toBeInTheDocument();
    expect(screen.getByLabelText('User avatar placeholder')).toBeInTheDocument();
  });
});

import React from 'react';
import { describe, expect, it } from 'vitest';
import { render, screen } from '@testing-library/react';
import '@testing-library/jest-dom';

import { MetricCards } from './MetricCards';

describe('MetricCards', () => {
  it('renders metric cards for provided metrics with their values and trend colors', () => {
    render(
      <MetricCards
        metrics={[
          {
            id: 'revenue',
            label: 'Revenue',
            value: '$12,400',
            change: '+8.2%',
            trendDirection: 'up',
          },
          {
            id: 'churn',
            label: 'Churn',
            value: '2.1%',
            change: '-0.4%',
            trendDirection: 'down',
          },
        ]}
      />,
    );

    expect(screen.getByLabelText('Revenue')).toBeInTheDocument();
    expect(screen.getByLabelText('Churn')).toBeInTheDocument();
    expect(screen.getByText('$12,400')).toBeInTheDocument();
    expect(screen.getByText('2.1%')).toBeInTheDocument();
    expect(screen.getByText('+8.2%')).toHaveStyle({ color: 'rgb(5, 150, 105)' });
    expect(screen.getByText('-0.4%')).toHaveStyle({ color: 'rgb(220, 38, 38)' });
  });

  it('renders an empty state when metrics are missing or empty', () => {
    const { rerender } = render(<MetricCards />);

    expect(screen.getByText('No metrics available')).toBeInTheDocument();

    rerender(<MetricCards metrics={[]} />);

    expect(screen.getByText('No metrics available')).toBeInTheDocument();
  });

  it('falls back to default labels, values, change text, and neutral color for incomplete metrics', () => {
    render(
      <MetricCards
        metrics={[
          {
            label: '   ',
            value: '   ',
            change: '',
          },
        ]}
      />,
    );

    expect(screen.getByLabelText('Untitled metric')).toBeInTheDocument();
    expect(screen.getByText('Untitled metric')).toBeInTheDocument();
    expect(screen.getByText('--')).toBeInTheDocument();

    const changeText = screen.getByText('No change data');
    expect(changeText).toBeInTheDocument();
    expect(changeText).toHaveStyle({ color: 'rgb(100, 116, 139)' });
  });
});

