import * as React from 'react';
import { render, screen } from '@testing-library/react';
import { describe, expect, it, vi } from 'vitest';
import ChartsSection from './ChartsSection';

vi.mock('recharts', () => {
  const React = require('react');

  const makeComponent =
    (testId: string) =>
    ({ children, ...props }: any) =>
      React.createElement('div', { 'data-testid': testId, ...props }, children);

  return {
    ResponsiveContainer: makeComponent('responsive-container'),
    LineChart: makeComponent('line-chart'),
    BarChart: makeComponent('bar-chart'),
    CartesianGrid: makeComponent('cartesian-grid'),
    XAxis: makeComponent('x-axis'),
    YAxis: makeComponent('y-axis'),
    Legend: makeComponent('legend'),
    Tooltip: makeComponent('tooltip'),
    Line: makeComponent('line'),
    Bar: makeComponent('bar'),
    Cell: makeComponent('cell'),
  };
});

describe('ChartsSection', () => {
  it('renders both chart cards and chart content when trend and category data are provided', () => {
    render(
      <ChartsSection
        trendData={[
          { label: 'Mon', value: 10, secondaryValue: 4, annotation: 'steady' },
          { label: 'Tue', value: 14, secondaryValue: 6, annotation: 'up' },
        ]}
        categoryData={[
          { id: 'a', label: 'Alpha', value: 40, color: '#111111', percentage: 40, detail: 'Top segment' },
          { id: 'b', label: 'Beta', value: 60, color: '#222222', percentage: 60, detail: 'Growth segment' },
        ]}
      />,
    );

    expect(
      screen.getByRole('region', { name: 'Charts overview section' }),
    ).toBeInTheDocument();
    expect(screen.getByText('7-Day Performance Trend')).toBeInTheDocument();
    expect(screen.getByText('Category Distribution')).toBeInTheDocument();

    expect(screen.getByTestId('line-chart')).toBeInTheDocument();
    expect(screen.getByTestId('bar-chart')).toBeInTheDocument();

    expect(
      screen.queryByText(/Trend data is unavailable right now/i),
    ).not.toBeInTheDocument();
    expect(
      screen.queryByText(/Category data is unavailable right now/i),
    ).not.toBeInTheDocument();
  });

  it('renders placeholder messages when both datasets are missing', () => {
    render(<ChartsSection />);

    expect(
      screen.getByText(/Trend data is unavailable right now\. Add a seven-day dataset to display the line chart\./i),
    ).toBeInTheDocument();
    expect(screen.queryByTestId('line-chart')).not.toBeInTheDocument();

    expect(screen.getByText(/Category data is unavailable right now/i)).toBeInTheDocument();
    expect(screen.queryByTestId('bar-chart')).not.toBeInTheDocument();
  });

  it('handles partial data by showing the available chart and the missing-data placeholder', () => {
    render(
      <ChartsSection
        trendData={[{ label: 'Wed', value: 8, secondaryValue: 2, annotation: 'ok' }]}
        categoryData={[]}
      />,
    );

    expect(screen.getByTestId('line-chart')).toBeInTheDocument();
    expect(screen.queryByText(/Trend data is unavailable right now/i)).not.toBeInTheDocument();

    expect(screen.queryByTestId('bar-chart')).not.toBeInTheDocument();
    expect(screen.getByText(/Category data is unavailable right now/i)).toBeInTheDocument();
  });
});

import React from 'react';
import { render, screen, within } from '@testing-library/react';
import { describe, expect, it } from 'vitest';
import RecentActivity from './RecentActivity';

describe('RecentActivity', () => {
  it('renders the empty state when items are missing or empty', () => {
    const { rerender } = render(<RecentActivity />);

    expect(screen.getByText('No recent activity')).toBeInTheDocument();
    expect(screen.queryByRole('list')).not.toBeInTheDocument();

    rerender(<RecentActivity items={[]} />);

    expect(screen.getByText('No recent activity')).toBeInTheDocument();
    expect(screen.queryByRole('list')).not.toBeInTheDocument();
  });

  it('sorts activities by newest timestamp first and renders core metadata', () => {
    render(
      <RecentActivity
        items={[
          {
            id: 'older',
            title: 'Older activity',
            description: 'Completed setup',
            status: 'completed',
            timestamp: '2024-01-02T09:00:00.000Z',
            category: 'Onboarding',
            userName: 'Taylor',
          },
          {
            id: 'newer',
            title: 'Newest activity',
            description: 'Created deployment',
            status: 'in-progress',
            timestamp: '2024-03-15T14:30:00.000Z',
            category: 'Release',
            userName: 'Jordan',
          },
        ]}
      />,
    );

    const list = screen.getByRole('list');
    const items = within(list).getAllByRole('listitem');

    expect(within(items[0]).getByRole('heading', { name: 'Newest activity' })).toBeInTheDocument();
    expect(within(items[0]).getByText('Created deployment')).toBeInTheDocument();
    expect(within(items[0]).getByText('in progress')).toBeInTheDocument();
    expect(within(items[0]).getByText('Release')).toBeInTheDocument();
    expect(within(items[0]).getByText('Jordan')).toBeInTheDocument();
    expect(within(items[0]).getByText(new Intl.DateTimeFormat(undefined, {
      dateStyle: 'medium',
      timeStyle: 'short',
    }).format(new Date('2024-03-15T14:30:00.000Z')))).toBeInTheDocument();

    expect(within(items[1]).getByRole('heading', { name: 'Older activity' })).toBeInTheDocument();
  });

  it('falls back for missing title/detail/time and pushes invalid timestamps to the end', () => {
    render(
      <RecentActivity
        items={[
          {
            id: 'invalid',
            title: '   ',
            status: 'needs-review',
            timestamp: 'not-a-date',
          },
          {
            id: 'valid',
            title: 'Valid activity',
            description: 'Has a valid timestamp',
            timestamp: '2024-02-01T10:00:00.000Z',
          },
          {
            id: 'missing-all',
          },
        ]}
      />,
    );

    const items = within(screen.getByRole('list')).getAllByRole('listitem');

    expect(within(items[0]).getByRole('heading', { name: 'Valid activity' })).toBeInTheDocument();

    expect(within(items[1]).getByRole('heading', { name: 'Untitled activity' })).toBeInTheDocument();
    expect(within(items[1]).getByText('Needs review')).toBeInTheDocument();
    expect(within(items[1]).getByText('needs review')).toBeInTheDocument();
    expect(within(items[1]).getByText('Time unavailable')).toBeInTheDocument();

    expect(within(items[2]).getByRole('heading', { name: 'Untitled activity' })).toBeInTheDocument();
    expect(within(items[2]).getByText('Status unavailable')).toBeInTheDocument();
    expect(within(items[2]).getByText('Time unavailable')).toBeInTheDocument();
  });
});

