import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, expect, it } from 'vitest';

import App from './App';
import { navigationItems } from './data/dashboardData';

describe('App', () => {
  it('renders the dashboard with the initially active navigation item content', () => {
    render(<App />);

    const initialItem = navigationItems.find((item) => item.isActive) ?? navigationItems[0];

    expect(
      screen.getByRole('heading', { level: 1, name: initialItem.label }),
    ).toBeInTheDocument();
    expect(screen.getByText(initialItem.description ?? 'Operational insights for your team.')).toBeInTheDocument();
    expect(
      screen.getByText(
        'All dashboard data is rendered locally with no routing, background sync, or network requests.',
      ),
    ).toBeInTheDocument();

    const activeNavButton = screen.getByRole('button', { name: new RegExp(initialItem.label, 'i') });
    expect(activeNavButton).toHaveAttribute('aria-current', 'page');
  });

  it('updates the selected section when a different navigation item is chosen', async () => {
    const user = userEvent.setup();
    render(<App />);

    const targetItem = navigationItems.find((item) => item.id === 'analytics') ?? navigationItems[1];
    await user.click(screen.getByRole('button', { name: new RegExp(targetItem.label, 'i') }));

    expect(screen.getByRole('heading', { level: 1, name: targetItem.label })).toBeInTheDocument();
    expect(screen.getByText(targetItem.description ?? 'Operational insights for your team.')).toBeInTheDocument();
    expect(screen.getByRole('button', { name: new RegExp(targetItem.label, 'i') })).toHaveAttribute(
      'aria-current',
      'page',
    );
  });

  it('falls back to generic header copy when a navigation item without description is selected', async () => {
    const user = userEvent.setup();
    render(<App />);

    const targetItem = navigationItems.find((item) => item.id === 'settings')!;
    await user.click(screen.getByRole('button', { name: new RegExp(targetItem.label, 'i') }));

    expect(screen.getByRole('heading', { level: 1, name: targetItem.label })).toBeInTheDocument();
    expect(screen.getByText('Operational insights for your team.')).toBeInTheDocument();
  });
});

